        ["thermal.now"] = ("Now", "Зараз"),
        ["thermal.max"] = ("Maximum, next 30 days", "Максимум, наступні 30 діб"),
        ["thermal.night"] = ("Minimum, next 30 days", "Мінімум, наступні 30 діб"),
