        ["thermal.max.window"] = ("Maximum in the window", "Максимум у вікні"),
        ["thermal.night.window"] = ("Minimum in the window", "Мінімум у вікні"),
        ["thermal.trap"] = ("No direct sunlight at this point in the modelled year. With direct sunlight as its only input the model would show only the column cooling towards about 24 K, so no temperature is given. Shadowed surfaces are warmed by sunlight scattered and infrared emitted by the surrounding terrain: the Diviner Polar Resource Product (thermal model fitted to Diviner observations, Paige et al. 2010) gives annual maxima of about 50 to 260 K for such cells, median about 100 K (−175 °C), below the temperature at which water ice sublimates significantly.", "Прямого сонячного світла в цій точці за модельний рік немає. Модель, у якої єдине джерело тепла пряме сонячне світло, показала б лише охолодження стовпа до приблизно 24 K, тому температуру не наведено. Затінені поверхні нагріваються світлом, розсіяним рельєфом навколо, і його інфрачервоним випромінюванням: Diviner Polar Resource Product (теплова модель, підігнана до спостережень Diviner, Paige et al. 2010) дає для таких клітинок річні максимуми приблизно 50–260 K, медіана близько 100 K (−175 °C), що нижче температури помітної сублімації водяного льоду."),
        ["thermal.note"] = ("Regolith heat model of Hayne et al. (2017), as used for the Diviner global regolith maps: density and conductivity increase with depth, heat capacity is temperature-dependent, heat stored in the regolith is released at night. Level surface, direct sunlight only; scattered and infrared flux from the surrounding terrain is not included, so locations in long shadow are biased cold.", "Теплова модель реголіту Hayne et al. (2017), використана для глобальних карт реголіту Diviner: густина і теплопровідність зростають з глибиною, теплоємність залежить від температури, тепло, накопичене реголітом, віддається вночі. Горизонтальна поверхня, лише пряме сонячне світло; розсіяний та інфрачервоний потік від рельєфу навколо не враховано, тому для місць у довгій тіні температура занижена."),
        ["thermal.note.tilted"] = ("Regolith heat model of Hayne et al. (2017), as used for the Diviner global regolith maps, on a surface tilted by the mean slope of the terrain patch around the site (480 m baseline on 100 m patches, 2 km on 1 km patches). Direct sunlight only; scattered and infrared flux from the surrounding terrain is not included, so locations in long shadow are biased cold.", "Теплова модель реголіту Hayne et al. (2017), використана для глобальних карт реголіту Diviner, на поверхні з нахилом, рівним середньому схилу ділянки рельєфу навколо місця (база 480 м на ділянках з кроком 100 м, 2 км на ділянках з кроком 1 км). Лише пряме сонячне світло; розсіяний та інфрачервоний потік від рельєфу навколо не враховано, тому для місць у довгій тіні температура занижена."),
        ["dsn.title"] = ("Deep Space Network", "Мережа далекого космічного зв'язку DSN"),
        ["dsn.link"] = ("Link via DSN, next 30 days", "Зв'язок через DSN, наступні 30 діб"),
        ["dsn.gap"] = ("Longest gap in the link", "Найдовша перерва зв'язку"),
        ["dsn.delay"] = ("Signal delay", "Затримка сигналу"),
        ["dsn.delayValue"] = ("{0} s one way, {1} s there and back", "{0} с в один бік, {1} с туди й назад"),
        ["dsn.note"] = ("A direct link requires the centre of Earth above the site horizon and the Moon at least 10° above one of the three DSN antenna complexes. DSN is used here as the reference ground network; antenna schedules, maintenance and outages are not modelled, and the network is oversubscribed (NASA OIG, 2023).", "Прямий зв'язок можливий, коли центр Землі над горизонтом місця, а Місяць не нижче 10° над одним із трьох комплексів антен DSN. DSN тут — еталонна наземна мережа; розклад антен, обслуговування й аварії не моделюються, а мережа перевантажена (NASA OIG, 2023)."),
        ["dsn.globe"] = ("On the 3D Earth, bright dots are the complexes that see the Moon at least 10° above the horizon now.", "На 3D-Землі яскраві точки — комплекси, які зараз бачать Місяць не нижче 10° над горизонтом."),
        ["dsn.lane"] = ("Gap: no DSN antenna sees the Moon", "Перерва: жодна антена DSN не бачить Місяць"),
        ["power.title"] = ("Power from 1 m² of solar cells", "Енергія з 1 м² сонячних елементів"),
