        ["power.battery"] = ("Battery: 100 W × longest stretch with no panel power", "Батарея: 100 Вт × найдовший проміжок без живлення від панелей"),
        ["power.perDay"] = ("{0} kWh a day", "{0} кВт·год на добу"),
