        ["report.quantity.verdicts"] = ("Screening assessment", "Попередня оцінка"),
        ["report.quantity.radio"] = ("Surface radio link", "Наземний радіозв'язок"),
        ["report.method.radio"] = ("Line of sight from an antenna on a 4 m mast at the site to a receiver 1.5 m above the ground, over the LOLA 80 m polar DEM: 1440 rays in 80 m steps to 22 km, lunar curvature included. Shares are weighted by area within 2 km and 10 km; the visible area is counted to 22 km. Heights, range and the 2 km radius follow LunarRF.", "Пряма видимість з антени на щоглі 4 м у місці посадки до приймача на 1.5 м над поверхнею по полярній моделі LOLA 80 м: 1440 променів кроком 80 м до 22 км, з урахуванням кривизни Місяця. Частки зважені за площею в радіусі 2 і 10 км; видима площа рахується до 22 км. Висоти, дальність і радіус 2 км взято з LunarRF."),
        ["report.acc.radio"] = ("Against the LunarRF candidate table (20 m DEM): correlation 0.988 within 2 km, 0.995 within 10 km, 0.992 for the area at 1328 landing-site candidates; the 80 m DEM gives slightly higher shares (+0.03 within 2 km). Line of sight only: LunarRF finds that a mast at 1.8 GHz covers a median 94% of this area. Path loss, antenna pattern, interference and relays are not modelled.", "Порівняно з таблицею кандидатів LunarRF (рельєф 20 м): кореляція 0.988 у радіусі 2 км, 0.995 у радіусі 10 км, 0.992 для площі на 1328 кандидатах біля місць посадки; рельєф 80 м дає трохи більші частки (+0.03 у радіусі 2 км). Лише пряма видимість: за LunarRF щогла на 1.8 ГГц покриває в медіані 94% цієї площі. Втрати на трасі, діаграма антени, завади і ретрансляція не моделюються."),
        ["report.radio.note"] = ("Line of sight is the condition for a direct surface link between the lander and a rover or astronaut; it does not depend on the date.", "Пряма видимість є умовою прямого наземного зв'язку між посадковим модулем і ровером чи астронавтом; вона не залежить від дати."),
        ["report.slope.nac"] = ("LROC NAC stereo terrain {0}", "Стереорельєф LROC NAC {0}"),
        ["report.slope.nacValue"] = ("{0} over {1}, {2} over {3} (median)", "{0} на базі {1}, {2} на базі {3} (медіана)"),
        ["report.slope.nacNote"] = ("Metre-scale stereo terrain around the landing point shows slopes that the LOLA patch smooths out.", "Метровий стереорельєф навколо точки посадки показує схили, які ділянка LOLA згладжує."),
        ["report.acc.siteCustom"] = ("Coordinates as entered by the user.", "Координати, як їх ввів користувач."),
        ["report.method.elevation.pole80"] = ("Height above the 1737.4 km reference sphere from the LOLA 80 m south pole DEM LDEM_80S_80MPP_ADJ at the point.", "Висота над сферою 1737.4 км з полярної моделі LOLA LDEM_80S_80MPP_ADJ (80 м) у точці."),
        ["report.acc.elevation.pole80"] = ("DEM cell 80 m; the height is interpolated between cell centres.", "Клітинка моделі 80 м; висоту інтерпольовано між центрами клітинок."),
        ["report.moreRows"] = ("Show {0} more (all of them are in JSON and CSV)", "Показати ще {0} (усі є в JSON і CSV)"),
        ["report.coordSource"] = ("Coordinates:", "Координати:"),
        ["report.numbers.title"] = ("Sun and Earth in numbers", "Сонце і Земля в числах"),
        ["report.num.sunrises"] = ("Sunrises / sunsets", "Сходи / заходи Сонця"),
        ["report.num.earthrises"] = ("Earthrises / Earthsets", "Сходи / заходи Землі"),
        ["report.num.elevation"] = ("Elevation min / mean / max", "Висота мін. / середня / макс."),
        ["report.num.azimuth"] = ("Azimuth range", "Діапазон азимута"),
        ["report.num.sunDistance"] = ("Distance", "Відстань"),
        ["report.num.irradiance"] = ("Sunlight above the surface", "Сонячне світло над поверхнею"),
        ["report.num.sunDisc"] = ("Disc diameter at the start", "Діаметр диска на старті"),
        ["report.num.peak"] = ("Vertical panel, peak", "Вертикальна панель, пік"),
        ["report.num.mean"] = ("mean", "середня"),
        ["report.num.energy"] = ("Energy over the window, vertical / flat", "Енергія за вікно, вертикальна / горизонтальна"),
        ["report.num.earthDistance"] = ("Distance", "Відстань"),
        ["report.num.earthDisc"] = ("Disc diameter", "Діаметр диска"),
        ["report.num.phase"] = ("Earth lit at the start", "Освітлена частина Землі на старті"),
        ["report.num.station"] = ("Moon 10° or more above {0}", "Місяць не нижче 10° над {0}"),
        ["report.num.note"] = ("Elevations are the centre of the disc, apparent from the site, without refraction (the Moon has no atmosphere). Energy is for 1 m² at 30% efficiency.", "Висоти дано для центру диска з місця, без рефракції (на Місяці немає атмосфери). Енергія для 1 м² з ККД 30%."),
        ["report.unit.au"] = ("au", "а. о."),
        ["report.unit.wm2"] = ("W/m²", "Вт/м²"),
        ["report.unit.w"] = ("W", "Вт"),
        ["report.unit.kwh"] = ("kWh", "кВт·год"),
        ["report.method.title"] = ("Method and accuracy", "Метод і точність"),
        ["report.method.quantity"] = ("Quantity", "Величина"),
        ["report.method.how"] = ("How it is computed", "Як рахується"),
        ["report.method.accuracy"] = ("Accuracy and limits", "Точність і обмеження"),
        ["report.method.refs"] = ("Sources", "Джерела"),
        ["report.method.landing"] = ("At the start of the window, taken as touchdown: Sun and Earth elevation and azimuth, height above the terrain horizon, visible part of the Sun disc, DSN complexes with the Moon 10° up. Apollo planning required landing in morning sunlight 7° to 20° above the horizon (Jones 1967); the flown landings ranged from about 5° (Apollo 12) to 15° (Apollo 16). The check here requires a rising Sun within that band. Shadow length on level ground is height / tan(Sun elevation).", "На початку вікна, взятому як момент посадки: висота і азимут Сонця й Землі, висота над горизонтом рельєфу, видима частина диска Сонця, комплекси DSN, над якими Місяць вище 10°. Планування Apollo вимагало посадки у ранковому світлі з Сонцем на 7–20° над горизонтом (Jones 1967); фактичні посадки були від приблизно 5° (Apollo 12) до 15° (Apollo 16). Тут перевірка вимагає Сонця, що піднімається, у цьому діапазоні. Довжина тіні на рівній поверхні дорівнює висоті / tan(висота Сонця)."),
        ["report.acc.landing"] = ("Shadow lengths are for level ground; on slopes facing away from the Sun they are longer. Example heights: person 1.8 m, small lander 4 m, large lander 50 m.", "Довжини тіней для рівної поверхні; на схилах, повернутих від Сонця, вони більші. Приклади висот: людина 1.8 м, малий апарат 4 м, великий 50 м."),
        ["report.method.battery"] = ("Battery full at touchdown, charged by a 1 m² panel turned to the Sun with the power model above, constant 100 W load, 30-minute steps. 80% of the capacity is usable, charge and discharge efficiency 95%. Shown for 2, 5, 10, 20 and 50 kWh.", "Батарея повна в момент посадки, заряджається від панелі 1 м², повернутої до Сонця, за моделлю енергії вище, постійне навантаження 100 Вт, крок 30 хв. Корисна ємність 80%, ККД заряду і розряду 95%. Для 2, 5, 10, 20 і 50 кВт·год."),
        ["report.acc.battery"] = ("No heater power at night, no capacity fade and no cold derating of the cells. For a mission the battery is sized against its own arrays and loads.", "Без обігріву вночі, без старіння і без втрати ємності на холоді. Для реальної місії ємність батареї визначають її власні панелі й навантаження."),
        ["report.method.safehaven"] = ("Steps in the window with less than half of the Sun disc and no Earth centre above the terrain horizon. The longest such stretch is compared with the VIPER limit of 50 hours, its endurance in minimum power mode (Shirley and Balaban 2022). For a window of at least one lunation the total is also scaled to 29.53 days and compared with the same 50 hours; shorter windows are only judged on the longest stretch.", "Кроки у вікні, коли над горизонтом рельєфу менше половини диска Сонця і немає центру Землі. Найдовший такий відрізок порівнюється з межею VIPER 50 годин, його витривалістю в режимі мінімальної потужності (Shirley and Balaban 2022). Для вікна від одного місячного місяця сумарний час також перераховується на 29.53 доби і порівнюється з тими самими 50 годинами; коротші вікна оцінюються лише за найдовшим відрізком."),
        ["report.acc.safehaven"] = ("VIPER applied the limit to the places where the rover waits out the dark. Here it is applied to the site itself, and darkness means less than half of the Sun disc.", "VIPER застосовував цю межу до місць, де ровер перечікує темряву. Тут її застосовано до самого місця, а темрява означає менше половини диска Сонця."),
        ["report.method.slope"] = ("Slope from the terrain patch around the site by central differences over two cells: at the site, mean and maximum within 1 km (3 km for 1 km patches), share of cells at 15° or more. 15° is the VIPER rover traverse limit, used here only as a screening threshold: lander limits are vehicle-specific and need metre-scale terrain.", "Схил із фрагмента рельєфу навколо місця, центральні різниці через дві клітинки: у точці, середній і максимальний у радіусі 1 км (3 км для фрагментів з кроком 1 км), частка клітинок від 15°. 15° це межа руху ровера VIPER, тут лише як поріг для відсіву: межі для посадкових апаратів залежать від апарата і потребують рельєфу з метровим кроком."),
        ["report.acc.slope"] = ("The baseline is two cells (200 m for polar patches, 2 km elsewhere), so boulders and small craters are not seen.", "База два кроки сітки (200 м для полярних фрагментів, 2 км для інших), тому каміння і малих кратерів не видно."),
        ["report.method.dispersion"] = ("Time: the same window started 2, 4 and 6 hours earlier or later (VIPER tested its traverse plans with a start time spread of about 2 h). Position: horizon recomputed from the terrain patch at 8 points on two circles around the site. Terrain outside the patch is taken from the site horizon.", "Час: те саме вікно зі стартом на 2, 4 і 6 год раніше або пізніше (VIPER перевіряв свої плани руху з розкидом старту близько 2 год). Місце: горизонт перераховано з фрагмента рельєфу у 8 точках на двох колах навколо місця. Рельєф поза фрагментом береться з горизонту місця."),
        ["report.acc.dispersion"] = ("The centre is recomputed in the same way, so all rows share one method. Polar patches are 40 km wide at 100 m, the others 300 km at 1 km.", "Центр перераховано тим самим способом, тож усі рядки отримано одним методом. Полярні фрагменти 40 км з кроком 100 м, інші 300 км з кроком 1 км."),
        ["report.method.monthly"] = ("Every calendar month of the four shipped years with the same horizon and DSN rules as the window.", "Кожен календарний місяць чотирьох років даних з тими самими горизонтом і правилами DSN, що й для вікна."),
        ["report.acc.monthly"] = ("Years after 2026-27 use the IAU 2015 rotation model in TDB, within 0.003° of SPICE.", "Роки після 2026-27 розраховано з моделлю обертання IAU 2015 у шкалі TDB, у межах 0.003° від SPICE."),
        ["report.method.eva"] = ("Share of sunlit time with the Sun under 5° (shadows longer than 11 times the object height), shadow factor at touchdown, share of the drawn route heading within 30° of the Sun azimuth at touchdown (walking towards the Sun), night surface temperature.", "Частка світлого часу, коли Сонце нижче 5° (тіні довші за 11 висот об'єкта), коефіцієнт тіні в момент посадки, частка намальованого маршруту з напрямом у межах 30° від азимута Сонця в момент посадки (рух у бік Сонця), нічна температура поверхні."),
        ["report.acc.eva"] = ("Route glare is evaluated with the Sun azimuth at touchdown only. Near the pole the Sun azimuth changes by about 12° a day.", "Засліплення на маршруті оцінено лише за азимутом Сонця в момент посадки. Біля полюса азимут Сонця змінюється приблизно на 12° за добу."),
