        ["report.eva.glare"] = ("Route heading into the Sun (±{0}°)", "Маршрут проти Сонця (±{0}°)"),
        ["report.eva.noRoute"] = ("no route drawn", "маршрут не намальовано"),
        ["report.eva.night"] = ("Coldest surface in the window", "Найхолодніша поверхня у вікні"),
        ["report.eva.note"] = ("At a Sun elevation of 1.5° to 2° shadows are 29 to 38 times the object height (about 27 times in the NASA OCHMO brief). Near the pole the Sun circles the full horizon once per lunation.", "При висоті Сонця 1.5–2° тіні в 29–38 разів довші за висоту об'єкта (близько 27 разів у брифі NASA OCHMO). Біля полюса Сонце проходить увесь горизонт за один місячний місяць."),
