        ["report.mount.0"] = ("Vertical, turns to the Sun (one-axis)", "Вертикальна, повертається за Сонцем"),
        ["report.mount.1"] = ("Vertical, fixed, best direction {0}°", "Вертикальна, нерухома, найкращий напрям {0}°"),
        ["report.mount.2"] = ("Vertical, fixed, worst direction {0}°", "Вертикальна, нерухома, найгірший напрям {0}°"),
        ["report.mount.3"] = ("Four fixed vertical faces (lander body)", "Чотири нерухомі вертикальні грані (корпус апарата)"),
        ["report.mount.4"] = ("Flat, on the top deck", "Горизонтальна, на верхній палубі"),
        ["report.mount.note"] = ("Fixed directions tried every 45° of azimuth. Near the pole a cylindrical fixed array needs roughly three times the cells of a Sun-tracking one (Fincannon, NASA GRC).", "Нерухомі напрями перебрано через кожні 45° азимута. Біля полюса нерухомий циліндричний масив потребує приблизно втричі більше елементів, ніж той, що стежить за Сонцем (Fincannon, NASA GRC)."),
        ["nav.incidents"] = ("Tipped landers", "Перекинуті апарати"),
        ["inc.title"] = ("Tipped landers: solar power in a non-nominal attitude", "Перекинуті апарати: сонячне живлення при нештатному положенні"),
        ["inc.lede"] = ("Three recent lunar landers came to rest on their side or nose (SLIM, IM-1, IM-2). From DE440 positions, the LOLA terrain horizon and the lander attitude, Shadowline computes when the panels are illuminated and compares the result with the events reported by the mission teams.", "Три нещодавні місячні апарати після посадки опинилися на боці або на носі (SLIM, IM-1, IM-2). З положень DE440, горизонту рельєфу LOLA і орієнтації апарата Shadowline розраховує, коли панелі освітлені, і порівнює результат з подіями, про які повідомили команди місій."),
        ["inc.cases"] = ("Cases", "Випадки"),
        ["inc.unavailable"] = ("Incident data could not be loaded.", "Не вдалося завантажити дані про випадки."),
        ["inc.slim.name"] = ("SLIM, JAXA, 2024", "SLIM, JAXA, 2024 р."),
        ["inc.im1.name"] = ("IM-1 Odysseus, 2024", "IM-1 Odysseus, 2024 р."),
        ["inc.im2.name"] = ("IM-2 Athena, 2025", "IM-2 Athena, 2025 р."),
        ["inc.blueghost1.name"] = ("Blue Ghost M1, 2025", "Blue Ghost M1, 2025 р."),
        ["inc.kind.tipped"] = ("tipped over", "перекинувся"),
        ["inc.kind.control"] = ("control case, upright", "контрольний випадок, штатне положення"),
        ["inc.slim.story"] = ("SLIM touched down at 00:20 JST on 20 January 2024 about 55 m from its target. About 50 m above the surface one main engine lost its nozzle; the lander drifted east and came to rest on its nose with the solar cells facing west. The Sun was in the east, the cells produced no power, and JAXA shut SLIM down 2.5 hours later with 12% of the battery charge left. On 28 January, after local noon, sunlight reached the cells and SLIM resumed operation. Although not designed to survive the lunar night, it resumed operation again in February, March and April.", "SLIM здійснив посадку о 00:20 JST 20 січня 2024 приблизно за 55 м від цілі. Приблизно за 50 м над поверхнею один головний двигун втратив сопло; апарат знесло на схід, і він опинився на носі сонячними елементами на захід. Сонце було на сході, елементи не виробляли енергії, і через 2.5 години JAXA вимкнула SLIM з 12% заряду батареї. 28 січня, після місцевого полудня, сонячне світло досягло елементів, і SLIM відновив роботу. Апарат не був розрахований на місячну ніч, проте відновлював роботу ще в лютому, березні й квітні."),
        ["inc.im1.story"] = ("Odysseus landed near Malapert A at 23:23 UTC on 22 February 2024, the first US landing since 1972. It came down faster than planned on a 12° slope, broke a leg and tipped over; the company reported it resting at about 30°, with one rectangular array meant to be vertical now on top. The lander operated for about six days, until that array was no longer illuminated on 28 and 29 February.", "Odysseus здійснив посадку біля Malapert A о 23:23 UTC 22 лютого 2024, це перша посадка США з 1972 року. Він опустився швидше, ніж планували, на схил 12°, зламав опору і перекинувся; компанія повідомила, що він лежить приблизно під 30°, а одна прямокутна панель, що мала стояти вертикально, опинилася згори. Апарат працював близько шести діб, доки ця панель не перестала освітлюватися 28 і 29 лютого."),
        ["inc.im2.story"] = ("Athena landed on Mons Mouton, about 160 km from the south pole, at 17:28 UTC on 6 March 2025. Its altimeter returned invalid readings; the lander struck the plateau, tipped over and came to rest on its side in the middle of a 20 m crater. The cells generated power, but less than required, and the mission ended about 13 hours after landing.", "Athena здійснила посадку на Mons Mouton, приблизно за 160 км від південного полюса, о 17:28 UTC 6 березня 2025. Альтиметр видавав хибні значення; апарат ударився об плато, перекинувся і опинився на боці посеред кратера діаметром 20 м. Елементи виробляли енергію, але менше потрібного, і місія завершилася приблизно через 13 годин після посадки."),
        ["inc.blueghost1.story"] = ("Firefly's Blue Ghost landed upright in Mare Crisium on 2 March 2025, operated through the whole lunar day and ceased operation on 16 March about 5 hours after sunset. It is the control case: for an upright lander the model reduces to the Sun-up condition.", "Blue Ghost компанії Firefly здійснив посадку у штатному положенні в Морі Криз 2 березня 2025, працював увесь місячний день і припинив роботу 16 березня приблизно через 5 годин після заходу Сонця. Це контрольний випадок: для апарата у штатному положенні модель зводиться до умови «Сонце над горизонтом»."),
        ["inc.fact.landed"] = ("Landed", "Посадка"),
        ["inc.im2.landingNote"] = ("Touchdown 12:28:50 p.m. EST (17:28:50 UTC) per Spaceflight Now; other press reports give about 12:30 p.m. EST.", "Посадка о 12:28:50 EST (17:28:50 UTC) за Spaceflight Now; інші повідомлення преси дають близько 12:30 EST."),
        ["inc.day.before"] = ("before", "до"),
        ["inc.day.after"] = ("or later", "або пізніше"),
        ["inc.fact.place"] = ("Place", "Місце"),
        ["inc.fact.globe"] = ("landing day on the globe", "день посадки на глобусі"),
        ["inc.fact.attitude"] = ("Attitude", "Положення"),
        ["inc.fact.vehicle"] = ("Vehicle", "Апарат"),
        ["inc.fact.ephemeris"] = ("Sun and Earth", "Сонце і Земля"),
        ["inc.fact.ephemerisValue"] = ("DE440 every 30 min from {0}, {1} days, {2}", "DE440 кожні 30 хв від {0}, діб: {1}, {2}"),
        ["inc.fact.horizonYes"] = ("terrain horizon from LOLA", "горизонт рельєфу з LOLA"),
        ["inc.fact.horizonNo"] = ("flat horizon", "плаский горизонт"),
        ["inc.slim.attitude"] = ("Nose down, about 90° from the planned attitude, solar cells facing west.", "На носі, приблизно 90° від запланованої орієнтації, сонячні елементи на захід."),
        ["inc.im1.attitude"] = ("About 30° above the horizontal, resting on a tank; one array on top at 30° to the horizontal, direction not published.", "Приблизно 30° до горизонту, спирається на бак; одна панель згори під 30° до горизонту, напрям не опубліковано."),
        ["inc.im2.attitude"] = ("On its side in the middle of a 20 m crater, panels not facing the Sun, dust on the panels.", "На боці посеред кратера 20 м, панелі не до Сонця, на панелях пил."),
        ["inc.blueghost1.attitude"] = ("Upright, nominal landing.", "Рівно, штатна посадка."),
        ["inc.slim.vehicle"] = ("Size 2.4 × 1.7 × 2.7 m, mass 200 kg dry and 700 to 730 kg with propellant (JAXA media kit). Thin-film triple-junction solar cell sheets by Sharp on the curved upper body, SUS laminate battery. Panel area and output were not published.", "Розмір 2.4 × 1.7 × 2.7 м, маса 200 кг суха і 700–730 кг з паливом (медіакіт JAXA). Тонкоплівкові триперехідні сонячні елементи Sharp на вигнутому верху корпусу, батарея в корпусі SUS. Площу і потужність панелей не публікували."),
        ["inc.im1.vehicle"] = ("Nova-C: 1908 kg at launch, 3.9 m tall, 2 m across. Three panels, one on the top deck and two on the body, 200 W combined maximum on the surface; 25 Ah battery on a 28 V bus.", "Nova-C: 1908 кг на старті, 3.9 м заввишки, 2 м у діаметрі. Три панелі, одна на верхній палубі і дві на корпусі, разом до 200 Вт на поверхні; батарея 25 А·год на шині 28 В."),
        ["inc.im2.vehicle"] = ("Nova-C class, as IM-1: three panels with 200 W combined maximum, 25 Ah battery on a 28 V bus.", "Клас Nova-C, як IM-1: три панелі разом до 200 Вт, батарея 25 А·год на шині 28 В."),
        ["inc.blueghost1.vehicle"] = ("Panel layout and battery are not used here: only the sunset time is compared.", "Розташування панелей і батарея тут не використовуються: порівнюється лише час заходу Сонця."),
        ["inc.events.title"] = ("Reported events", "Повідомлені події"),
        ["inc.events.lede"] = ("Every event below comes from the mission team or a report quoting it. Events marked fit train the model, events marked check are held back to test it, context events are shown but not used.", "Кожна подія нижче від команди місії або з повідомлення, що її цитує. Події «навчання» використовуються для підбору моделі, події «перевірка» відкладено, щоб її перевірити, події «контекст» показано, але не використано."),
        ["inc.events.when"] = ("When, UTC", "Коли, UTC"),
        ["inc.events.what"] = ("Event", "Подія"),
        ["inc.events.use"] = ("Used for", "Для чого"),
        ["inc.events.src"] = ("Source", "Джерело"),
        ["inc.use.fit"] = ("fit", "навчання"),
        ["inc.use.check"] = ("check", "перевірка"),
        ["inc.use.none"] = ("context", "контекст"),
        ["inc.fit.title"] = ("Panel orientation: inverse estimate", "Орієнтація панелі: зворотна оцінка"),
        ["inc.fit.method"] = ("Monte Carlo rejection sampling", "Монте-Карло з відкиданням"),
        ["inc.fit.lede.slim"] = ("The attitude of SLIM was never measured. Thousands of panel directions are drawn uniformly over the sphere, with a power threshold between 2% and 60% of full sunlight, and those consistent with the fit events are kept. The kept set is the estimate; the check events are then predicted from it.", "Орієнтацію SLIM ніхто не вимірював. Тисячі напрямів панелі вибираються рівномірно по сфері з порогом живлення від 2% до 60% повного сонячного світла, залишаються ті, що узгоджуються з подіями навчання. Залишений набір і є оцінкою; з нього прогнозуються події перевірки."),
        ["inc.fit.lede.im1"] = ("The array is known to lie 30° to the horizontal, so only its compass direction and the power threshold are drawn. The fit event is that the lander ran on solar power from 23 to 27 February; the check is the time it lost power.", "Відомо, що панель лежить під 30° до горизонту, тож перебираються лише її напрям за компасом і поріг живлення. Подія навчання: апарат працював від сонячних панелей з 23 по 27 лютого; перевірка: час, коли він втратив живлення."),
        ["inc.fit.running"] = ("Sampling panel directions: {0}%", "Вибірка напрямів панелі: {0}%"),
        ["inc.fit.accepted"] = ("panel directions kept / drawn", "напрямів панелі залишено / перебрано"),
        ["inc.fit.azimuth"] = ("panel azimuth, 90% from {0} to {1}", "азимут панелі, 90% від {0} до {1}"),
        ["inc.fit.elevation"] = ("panel elevation, 90% from {0} to {1}", "висота нормалі панелі, 90% від {0} до {1}"),
        ["inc.fit.elevationFixed"] = ("panel elevation, fixed by the reported tilt", "висота нормалі панелі, задана повідомленим нахилом"),
        ["inc.fit.threshold"] = ("power threshold of full sunlight, 90% from {0} to {1}", "поріг живлення від повного світла, 90% від {0} до {1}"),
        ["inc.fit.polar"] = ("Kept panel directions", "Залишені напрями панелі"),
        ["inc.fit.polarNote"] = ("Each dot is one kept panel direction seen from above: centre is straight up, the dashed ring is the horizon, the edge is straight down. The ring marks the direction reported by the mission team.", "Кожна точка це один залишений напрям панелі, вигляд згори: центр прямо вгору, пунктирне коло горизонт, край прямо вниз. Кільце позначає напрям, який повідомила команда місії."),
        ["inc.check.title"] = ("Held-out check", "Перевірка на відкладених подіях"),
        ["inc.check.prior"] = ("Before fit", "До навчання"),
        ["inc.check.post"] = ("After fit", "Після навчання"),
        ["inc.check.error"] = ("Timing error, h", "Похибка часу, год"),
        ["inc.check.note"] = ("Share of panel directions for which the event follows from the lighting. Before fit: all drawn directions; after fit: only the kept ones. Timing error: median and 90% range of the predicted moment minus the reported window, 0 when inside it.", "Частка напрямів панелі, для яких подія випливає з освітлення. До навчання: усі перебрані напрями; після навчання: лише залишені. Похибка часу: медіана і 90% розкид прогнозованого моменту мінус повідомлене вікно, 0 якщо всередині."),
        ["inc.kindobs.Power"] = ("Power at contact", "Живлення під час зв'язку"),
        ["inc.kindobs.PowerThroughout"] = ("Power throughout", "Живлення весь час"),
        ["inc.kindobs.NoPower"] = ("No power", "Немає живлення"),
        ["inc.kindobs.PowerLost"] = ("Power lost", "Живлення зникло"),
        ["inc.kindobs.Operations"] = ("Operations window", "Робоче вікно"),
        ["inc.kindobs.PowerLow"] = ("Low power", "Недостатнє живлення"),
        ["inc.kindobs.End"] = ("End of mission", "Кінець місії"),
        ["inc.kindobs.Hardware"] = ("Hardware", "Обладнання"),
        ["inc.errValue"] = ("{0} ({1} to {2})", "{0} (від {1} до {2})"),
        ["inc.hours"] = ("{0} h", "{0} год"),
        ["inc.crater.title"] = ("Direct sunlight on the crater floor", "Пряме сонячне світло на дні кратера"),
        ["inc.crater.lede"] = ("From landing to the end of the mission the Sun stood {0} to {1} above the horizon, and the terrain horizon from the LOLA map reached {2}. A 20 m crater is far below the map resolution, so its rim is added from measured depth-to-diameter ratios, depth from the rim crest to the floor: 0.11 to 0.17 for extremely fresh craters from 40 m to 400 m (Stopar et al. 2017), shallower when worn, about 0.2 for larger fresh craters (Pike 1977). A 20 m crater is below the smallest measured size, so this is an extrapolation.", "Від посадки до кінця місії Сонце стояло на {0}–{1} над горизонтом, а горизонт рельєфу з карти LOLA сягав {2}. Кратер 20 м значно менший за роздільність карти, тож його край додано з виміряних співвідношень глибини до діаметра, глибина від гребеня до дна: 0.11–0.17 для дуже свіжих кратерів від 40 до 400 м (Stopar et al. 2017), менше для зношених, близько 0.2 для більших свіжих (Pike 1977). Кратер 20 м менший за найменший виміряний, тож це екстраполяція."),
        ["inc.crater.ratio"] = ("Depth / diameter", "Глибина / діаметр"),
        ["inc.crater.height"] = ("Panel height", "Висота панелі"),
        ["inc.crater.rim"] = ("Rim above the horizon", "Край над горизонтом"),
        ["inc.crater.sun"] = ("Direct sunlight", "Пряме Сонце"),
        ["inc.crater.blocked"] = ("blocked", "закрите"),
        ["inc.crater.open"] = ("possible", "можливе"),
        ["inc.crater.battery"] = ("If the panels produced nothing, a 25 Ah, 28 V battery (700 Wh, the product of the published values) depleted in {0} h implies a net draw of about {1} W, or {2} W with 80% usable capacity; any panel input implies a higher load. The simulator below starts with this draw and no extra crater rim; the crater slider adds one.", "Якщо панелі нічого не виробляли, батарея 25 А·год на 28 В (700 Вт·год, добуток опублікованих значень), розряджена за {0} год, означає чисте споживання близько {1} Вт або {2} Вт за 80% корисної ємності; будь-яке живлення від панелей означає більше навантаження. Симулятор нижче починає з цього споживання і без додаткового валу кратера; повзунок кратера його додає."),
        ["inc.control.title"] = ("Sunset at an upright lander", "Захід Сонця над апаратом, що стоїть рівно"),
        ["inc.control.model"] = ("Sunset, Shadowline (last part of the disc behind the terrain horizon)", "Захід, Shadowline (остання частина диска за горизонтом рельєфу)"),
        ["inc.control.reported"] = ("Sunset implied by Firefly (end minus 5 hours)", "Захід, що випливає зі слів Firefly (кінець мінус 5 годин)"),
        ["inc.control.diff"] = ("Difference", "Різниця"),
        ["inc.control.note"] = ("The Sun sets here at about 0.5° per hour, so 2 hours correspond to about 1° of horizon. The horizon at this site comes from the global LOLA map at about 1.9 km, which does not resolve nearby relief, and the 5 hours are a rounded figure from one news report. A later model sunset is the sign expected from a smoothed horizon; one case is not sufficient to estimate a general error.", "Сонце тут сідає приблизно на 0.5° за годину, тож 2 години відповідають приблизно 1° горизонту. Горизонт тут з глобальної карти LOLA з кроком близько 1.9 км, яка не розрізняє близького рельєфу, а 5 годин це округлене значення з одного повідомлення. Пізніший захід у моделі має очікуваний знак для згладженого горизонту; одного випадку недостатньо для оцінки загальної похибки."),
        ["inc.sim.title"] = ("Attitude simulator", "Симулятор положення"),
        ["inc.sim.lede"] = ("Alternative attitudes. The panel starts at the posterior median; a posterior draw shows the spread of the result, and all values can be set manually. Area, efficiency, battery and load are assumptions unless given by the facts above; they change watts and charge, not whether the panel is illuminated.", "Інші положення. Панель задано медіаною апостеріорної оцінки; варіант з апостеріорної вибірки показує розкид результату, усі значення можна задати вручну. Площа, ККД, батарея й навантаження є припущеннями, якщо факти вище їх не дають; вони змінюють вати і заряд, але не те, чи освітлена панель."),
        ["inc.sim.lies"] = ("Attitude", "Положення"),
        ["inc.sim.presets"] = ("Attitude presets", "Готові положення"),
        ["inc.preset.case"] = ("As in this case", "Як у цьому випадку"),
