        ["inc.sim.wake"] = ("Wake-up power threshold", "Поріг потужності для пробудження"),
        ["inc.sim.kwh"] = ("kWh from the panels", "кВт·год з панелей"),
        ["inc.sim.awake"] = ("of the time in operation", "часу в роботі"),
