        ["inc.sim.afterH"] = ("after {0} h", "через {0} год"),
        ["inc.sim.never"] = ("never", "ніколи"),
        ["inc.chart.sun"] = ("Sun elevation and terrain horizon in its direction", "Висота Сонця і горизонт рельєфу в його напрямку"),
        ["inc.chart.sunEl"] = ("Sun", "Сонце"),
        ["inc.chart.horizon"] = ("Horizon", "Горизонт"),
        ["inc.chart.power"] = ("Power from the panels", "Потужність панелей"),
        ["inc.chart.panels"] = ("Panels", "Панелі"),
        ["inc.chart.wake"] = ("wake-up", "пробудження"),
        ["inc.chart.battery"] = ("Battery and state", "Батарея і стан"),
        ["inc.chart.charge"] = ("Charge", "Заряд"),
        ["inc.chart.on"] = ("Operating", "Робота"),
        ["inc.chart.note"] = ("Days from landing at {0}. Shaded: no Sun at the site. Coloured bands are the reported events: violet used for the fit, green held back for the check, grey context only.", "Дні від посадки о {0}. Затінено: Сонця в місці немає. Кольорові смуги це повідомлені події: фіолетові для навчання, зелені відкладені для перевірки, сірі лише для контексту."),
        ["inc.method.title"] = ("Method and limits", "Метод і обмеження"),
        ["inc.method.geometry"] = ("Sun", "Сонце"),
        ["inc.method.geometryText"] = ("Sun direction every 30 minutes from DE440 with light time and stellar aberration in the Moon frame (IAU 2015 rotation in TDB, within 0.003° of MOON_ME), seen from the site coordinates measured on LRO images. Visible area of the disc above the terrain horizon from LOLA, as on the rest of the site.", "Напрям на Сонце кожні 30 хвилин з DE440 з часом поширення світла і аберацією в системі Місяця (обертання IAU 2015 у шкалі TDB, у межах 0.003° від MOON_ME), з координат місця, виміряних на знімках LRO. Видима площа диска над горизонтом рельєфу з LOLA, як і на решті сайту."),
        ["inc.method.power"] = ("Power", "Живлення"),
        ["inc.method.powerText"] = ("Each flat panel receives irradiance × max(0, n̂ · ŝ) × area × efficiency × 0.80 system factor × dust. The efficiency is fixed, so the factor is Fincannon's 0.775 with its temperature terms kept and the distance term removed (the irradiance already uses the actual Sun distance). The panel normal n̂ is the body normal rotated by the spin about the vertical and the tilt towards a compass direction. The battery charges and discharges at 95%; the lander enters dormancy below 5% charge and resumes operation when the panels reach the wake-up power.", "Кожна пласка панель отримує освітленість × max(0, n̂ · ŝ) × площа × ККД × системний коефіцієнт 0.80 × пил. ККД сталий, тому коефіцієнт це 0.775 Fincannon зі складовими температури, але без складової відстані (освітленість уже враховує фактичну відстань до Сонця). Нормаль n̂ це нормаль у системі корпусу, повернута поворотом навколо вертикалі і нахилом у бік заданого азимута. Батарея заряджається і розряджається з ККД 95%; апарат переходить у сплячий режим нижче 5% заряду і відновлює роботу, коли панелі досягають потужності пробудження."),
        ["inc.method.inverse"] = ("Inverse estimate", "Зворотна оцінка"),
        ["inc.method.inverseText"] = ("One effective panel with unknown direction and an unknown share of full sunlight needed for power. Directions are drawn uniformly over the sphere (or the known tilt), thresholds uniformly from 2% to 60%, with a fixed seed. A draw is kept if every fit event follows from it. Check events are scored on the kept draws only.", "Одна ефективна панель з невідомим напрямом і невідомою часткою повного світла, потрібною для живлення. Напрями беруться рівномірно по сфері (або з відомим нахилом), пороги рівномірно від 2% до 60%, з фіксованим зерном. Варіант залишається, якщо з нього випливають усі події навчання. Події перевірки оцінюються лише на залишених варіантах."),
        ["inc.method.limits"] = ("Limits", "Обмеження"),
        ["inc.method.limitsText"] = ("Curved or partly shaded panels, light reflected from the ground and nearby slopes, heaters, the thermal state of the battery and the times chosen by the team for contact sessions are not modelled. A contact time shows when the lander had power, not when power first appeared.", "Вигнуті чи частково затінені панелі, світло, відбите від ґрунту і схилів, обігрівачі, тепловий стан батареї і вибір командою часу сеансів зв'язку не моделюються. Час зв'язку показує, коли апарат мав живлення, а не коли воно з'явилося вперше."),
        ["inc.print"] = ("Print report", "Друкувати звіт"),
        ["inc.json"] = ("Download JSON", "Завантажити JSON"),
        ["inc.steps"] = ("Steps", "Кроки"),
        ["inc.step.case"] = ("The lander", "Апарат"),
        ["inc.step.events"] = ("Reported events", "Повідомлені події"),
        ["inc.step.model"] = ("Model", "Модель"),
        ["inc.step.fit"] = ("Fit: panel orientation", "Навчання: орієнтація панелі"),
        ["inc.step.predict"] = ("Prediction", "Прогноз"),
        ["inc.step.validate"] = ("Validation", "Перевірка"),
        ["inc.step.whatif"] = ("Simulator", "Симулятор"),
        ["inc.answer.title"] = ("Result", "Результат"),
        ["inc.answer.wait"] = ("Sampling panel directions…", "Вибірка напрямів панелі…"),
        ["inc.answer.slim1"] = ("From the January events alone the panel faces azimuth {0} (90% interval {1} to {2}). JAXA reported west-facing cells on 25 January from its post-landing data, before any afternoon power, and expected SLIM to recover as the Sun moved west; the contact on the night of 28 January confirmed it. This estimate uses that contact, so the agreement rests on shared facts: no power in the morning and confirmed power in the afternoon.", "Лише з січневих подій панель дивиться на азимут {0} (90% інтервал від {1} до {2}). JAXA повідомила про елементи, повернуті на захід, 25 січня з даних після посадки, ще до будь-якого живлення вдень, і очікувала відновлення SLIM, коли Сонце зміститься на захід; зв'язок у ніч на 28 січня це підтвердив. Ця оцінка використовує цей зв'язок, тож збіг спирається на спільні факти: відсутність живлення вранці і підтверджене живлення вдень."),
        ["inc.answer.slim2"] = ("First power after landing: {0} (90% {1} to {2}). The contact on the night of 28 January was used for the fit, so agreement with it is not a test; the prediction is that power returned days before the contact.", "Перше живлення після посадки: {0} (90% від {1} до {2}). Зв'язок уночі 28 січня використано для навчання, тож збіг з ним не є перевіркою; прогноз полягає в тому, що живлення відновилося на кілька діб раніше за зв'язок."),
        ["inc.answer.slim3"] = ("Second lunar day, held-out prediction: first power {0} (90% {1} to {2}); telemetry was received at about 10:00 UTC on 25 February.", "Другий місячний день, прогноз без використання цих даних: перше живлення {0} (90% від {1} до {2}); телеметрію отримано близько 10:00 UTC 25 лютого."),
        ["inc.answer.im1a"] = ("For a lit array at 30° to the horizontal, six days of solar power constrain its azimuth to {0} (90% interval {1} to {2}).", "Для освітленої панелі під 30° до горизонту шість діб сонячного живлення обмежують її азимут значенням {0} (90% інтервал від {1} до {2})."),
        ["inc.answer.im1b"] = ("Predicted loss of panel power: {0} (90% {1} to {2}), before the local sunset at {3}. Reported: power lost on 28 to 29 February. The prediction is late: only {4} of kept draws place the loss in the reported window. Likely causes outside the model: shading of the panel by the lander body, final commands from the ground, battery state.", "Прогноз втрати живлення від панелі: {0} (90% від {1} до {2}), раніше за місцевий захід о {3}. Повідомлено: живлення зникло 28-29 лютого. Прогноз запізнюється: лише {4} залишених варіантів дають втрату в повідомленому вікні. Імовірні причини поза моделлю: затінення панелі корпусом, останні команди наземного управління, стан батареї."),
        ["inc.answer.im2"] = ("The Sun stood {0} to {1} above the horizon. Direct sunlight on a panel inside the 20 m crater needs a depth/diameter below {2} (panel 1 m above the floor) or {3} (2 m); measured fresh craters of 40 m and more are 0.11 to 0.17 deep, older ones shallower. The reported power right after landing points to a shallow, worn crater, a panel high on the lying lander or light reflected from the sunlit crater wall.", "Сонце стояло на {0}–{1} над горизонтом. Пряме світло на панель усередині кратера 20 м можливе лише при глибині/діаметрі менше {2} (панель на 1 м над дном) або {3} (2 м); виміряні свіжі кратери від 40 м мають 0.11–0.17, старші мілкіші. Повідомлене живлення одразу після посадки вказує на мілкий зношений кратер, панель високо на лежачому апараті або світло, відбите від освітленої стінки кратера."),
        ["inc.answer.bg"] = ("Upright control lander: the model gives sunset at {0}, the Firefly report implies {1}, a difference of {2} h.", "Контрольний апарат у штатному положенні: модель дає захід о {0}, зі слів Firefly випливає {1}, різниця {2} год."),
        ["inc.events.kind"] = ("Event type", "Тип події"),
        ["inc.use.derived"] = ("derived", "виведено"),
        ["inc.kindobs.Thermal"] = ("Thermal", "Тепловий режим"),
        ["inc.slim.notes"] = ("LRO laser ranging to SLIM uses its passive retroreflector and needs no power (performed on 24 May 2024, reported by NASA in July 2024), so it is not used as a power event.", "Лазерне вимірювання відстані з LRO до SLIM використовує пасивний відбивач і не потребує живлення (виконано 24 травня 2024, NASA повідомила в липні 2024), тому як подію живлення його не враховано."),
        ["inc.model.lede"] = ("One effective flat panel with unknown direction and an unknown share of full sunlight it needs before the lander has power. Everything else comes from data: Sun direction, distance and the terrain horizon.", "Одна ефективна пласка панель з невідомим напрямом і невідомою часткою повного світла, яка потрібна, щоб апарат мав живлення. Усе інше з даних: напрям і відстань до Сонця, горизонт рельєфу."),
        ["inc.model.diagram"] = ("Model data flow", "Потік даних моделі"),
        ["inc.diag.physics"] = ("Physics (known)", "Фізика (відома)"),
        ["inc.diag.inference"] = ("Inference (from the reported events)", "Висновок (з повідомлених подій)"),
        ["inc.diag.in"] = ("In: site, landing time, reported events with time windows, prior ranges.", "Вхід: місце, час посадки, повідомлені події з часовими вікнами, межі апріорних значень."),
        ["inc.diag.out"] = ("Out: kept draws (az, el, τ), intervals, P(power) over time, first and last power per lunar day, skill scores.", "Вихід: залишені варіанти (az, el, τ), інтервали, P(живлення) у часі, перше й останнє живлення в кожен місячний день, показники якості прогнозу."),
        ["inc.diag.eph.t"] = ("DE440 ephemeris", "Ефемериди DE440"),
        ["inc.diag.eph.a"] = ("Sun direction ŝ(t)", "напрям на Сонце ŝ(t)"),
        ["inc.diag.eph.b"] = ("distance r(t), 30 min", "відстань r(t), 30 хв"),
        ["inc.diag.terrain.t"] = ("LOLA horizon", "Горизонт LOLA"),
        ["inc.diag.terrain.a"] = ("h(az) at the site", "h(az) у місці"),
        ["inc.diag.terrain.b"] = ("visible disc f(t)", "видимий диск f(t)"),
        ["inc.diag.panel.t"] = ("Panel", "Панель"),
        ["inc.diag.panel.a"] = ("light u = E/S₀ · max(0, n̂·ŝ)", "світло u = E/S₀ · max(0, n̂·ŝ)"),
        ["inc.diag.panel.b"] = ("on if u ≥ τ", "живлення, якщо u ≥ τ"),
        ["inc.diag.events.t"] = ("Fit events", "Події навчання"),
        ["inc.diag.events.a"] = ("power, no power,", "живлення, немає,"),
        ["inc.diag.events.b"] = ("power lost", "зникло"),
        ["inc.diag.kept.t"] = ("Kept draws", "Залишені варіанти"),
        ["inc.diag.kept.a"] = ("prior × L(θ)", "апріорне × L(θ)"),
        ["inc.diag.kept.b"] = ("= posterior", "= апостеріорне"),
        ["inc.diag.predict.t"] = ("Prediction", "Прогноз"),
        ["inc.diag.predict.a"] = ("P(on at t)", "P(живлення в t)"),
        ["inc.diag.predict.b"] = ("checked on held-out", "перевірка на відкладених"),
        ["inc.model.operators"] = ("How each reported event is tested", "Як перевіряється кожна подія"),
        ["inc.model.rule"] = ("Rule for a draw θ", "Правило для варіанта θ"),
        ["inc.op.Power"] = ("on(t) at least once in [a, b]. A contact proves power at that time, so first power came at or before it (censored).", "on(t) хоча б раз у [a, b]. Зв'язок доводить живлення в цей час, тож перше живлення було тоді або раніше (цензуровані дані)."),
        ["inc.op.NoPower"] = ("on(t) never in [a, b].", "on(t) жодного разу в [a, b]."),
        ["inc.op.PowerThroughout"] = ("on(t) at every step of [a, b].", "on(t) на кожному кроці [a, b]."),
        ["inc.op.PowerLost"] = ("The on to off change closest to the window falls inside [a, b]; the timing error is its distance from the window.", "Найближчий до вікна перехід з on на off потрапляє в [a, b]; похибка часу це його відстань від вікна."),
        ["inc.model.algorithm"] = ("Algorithm", "Алгоритм"),
        ["inc.algo.1"] = ("Build ŝ(t) and E(t) on the 30 min grid of the case from DE440 and the LOLA horizon.", "Побудувати ŝ(t) і E(t) на 30-хвилинній сітці випадку з DE440 і горизонту LOLA."),
        ["inc.algo.2"] = ("Draw {0} values of θ = (az, el, τ) from the prior with a fixed random seed ({1}).", "Згенерувати {0} значень θ = (az, el, τ) з апріорного розподілу з фіксованим початковим значенням генератора ({1})."),
        ["inc.algo.3"] = ("Keep a draw only if every fit event holds under its rule.", "Залишити варіант, лише якщо для нього виконуються всі події навчання."),
        ["inc.algo.4"] = ("Summarise: circular median and 5 to 95% range of az, quantiles of el and τ.", "Підсумувати: кругова медіана і 5–95% az, квантилі el і τ."),
        ["inc.algo.5"] = ("Predict: for every kept draw find the first and last powered step in each lunar day, then take the median and the 90% range.", "Прогноз: для кожного залишеного варіанта знайти перший і останній крок з живленням у кожному місячному дні, потім медіану і 90% розкид."),
        ["inc.algo.6"] = ("Score the held-out events against simple baselines with the Brier and logarithmic scores.", "Оцінити відкладені події проти простих базових правил за оцінкою Brier і логарифмічною оцінкою."),
        ["inc.algo.7"] = ("Check the method itself on 200 synthetic landers with known attitude (tool IncidentCheck).", "Перевірити сам метод на 200 синтетичних апаратах з відомою орієнтацією (інструмент IncidentCheck)."),
        ["inc.model.inputs"] = ("Input data", "Вхідні дані"),
        ["inc.model.inputsText"] = ("For each lander: site coordinates, landing time, reported events with UTC time windows and their role (fit, check or context) with sources; Sun and Earth positions from DE440 at a 30 min step; the LOLA terrain horizon at a 0.5° azimuth step.", "Для кожного апарата: координати місця, час посадки, повідомлені події з часовими вікнами UTC і їхньою роллю (навчання, перевірка або контекст) з джерелами; положення Сонця і Землі з DE440 з кроком 30 хв; горизонт рельєфу LOLA з кроком 0.5° за азимутом."),
        ["inc.model.outputs"] = ("Results", "Результати"),
        ["inc.model.outputsText"] = ("Kept draws with their intervals, P(power) over time, first and last powered time per lunar day, scores per event and model. The JSON export at the end of the page contains all kept draws.", "Збережені вибірки з інтервалами, P(живлення) у часі, перший і останній момент живлення в кожну місячну добу, оцінки для кожної події й моделі. Експорт JSON наприкінці сторінки містить усі збережені вибірки."),
        ["inc.model.limits"] = ("Not modelled", "Не моделюється"),
        ["inc.model.limitsText"] = ("Battery and electronics temperature (charging below 0 °C, heaters, survival at night), light reflected from the ground (a few % of full sunlight on a panel facing down), self-shadowing and curved panels. Earth and ground-station visibility are checked in the validation step but not used in the fit. Contact times are treated only as proof of power at that time.", "Температура батареї й електроніки (заряд нижче 0 °C, обігрів, виживання вночі), світло, відбите від ґрунту (кілька % повного світла на панель, повернуту вниз), самозатінення і вигнуті панелі. Видимість Землі і наземних станцій перевіряється на кроці перевірки, але в навчанні не використовується. Час зв'язку вважається лише доказом живлення в той момент."),
        ["inc.model.repro"] = ("Reproducibility", "Відтворюваність"),
        ["inc.model.reproText"] = ("Monte Carlo sampling with {0} draws and a fixed random seed ({1}); results are identical on every run.", "Вибірка Монте-Карло з {0} варіантів з фіксованим початковим значенням генератора ({1}); результати однакові при кожному запуску."),
        ["inc.fit.none.im2"] = ("No timeline of power events is available for IM-2; the check is whether direct sunlight could reach the panels.", "Для IM-2 немає часової послідовності подій живлення; перевіряється, чи могло пряме сонячне світло досягти панелей."),
        ["inc.fit.none.blueghost1"] = ("Blue Ghost landed upright, so there is no attitude to estimate; the case tests the Sun and horizon chain alone.", "Blue Ghost здійснив посадку у штатному положенні, тож орієнтацію оцінювати не потрібно; цей випадок перевіряє лише ланцюжок Сонця і горизонту."),
        ["inc.fit.prior"] = ("prior", "апріорне"),
        ["inc.fit.posterior"] = ("posterior", "апостеріорне"),
        ["inc.fit.histAz"] = ("Panel azimuth", "Азимут панелі"),
        ["inc.fit.histEl"] = ("Panel normal elevation", "Висота нормалі панелі"),
        ["inc.fit.histTau"] = ("Threshold τ, % of full sunlight", "Поріг τ, % повного світла"),
        ["inc.fit.polarNoteNone"] = ("Each dot is one kept panel direction seen from above: centre is straight up, the dashed ring is the horizon, the edge is straight down. No direction was reported for this lander.", "Кожна точка це один залишений напрям панелі, вигляд згори: центр прямо вгору, пунктирне коло горизонт, край прямо вниз. Для цього апарата напрям не повідомлено."),
        ["inc.fit.scatter"] = ("Elevation against threshold", "Висота проти порогу"),
        ["inc.fit.scatterX"] = ("panel normal elevation", "висота нормалі панелі"),
        ["inc.fit.scatterNote"] = ("Kept draws fill most of the plane: the events weakly constrain the tilt (strongly downward panels are ruled out) and not the threshold; they mainly fix the direction.", "Залишені варіанти заповнюють більшу частину площини: події слабко обмежують нахил (панелі, сильно повернуті вниз, відкинуто) і не обмежують поріг; вони головно задають напрям."),
        ["inc.fit.read.slim"] = ("Interpretation: the events confine the direction to the western half of the sky and exclude strongly downward panels; they constrain the tilt weakly and the threshold not at all, whose posterior is close to the prior.", "Інтерпретація: події обмежують напрям західною половиною неба і виключають панелі, сильно повернуті вниз; нахил вони обмежують слабко, а поріг не обмежують зовсім, його апостеріорний розподіл близький до апріорного."),
        ["inc.fit.read.im1"] = ("The tilt is fixed by the reported 30°; only the compass direction is estimated. Other readings of the 30° are compared in the validation step.", "Нахил задано повідомленими 30°; оцінюється лише напрям за компасом. Інші прочитання цих 30° порівняно на кроці перевірки."),
        ["inc.crater.inverse"] = ("Inverse: a panel 1 m above the floor is directly lit only if the crater is shallower than {0} of its diameter, 2 m above only if shallower than {1}. The reported power right after landing then points to a worn, shallow crater or a panel high on the lander lying on its side; in both cases far less than the heaters and radio required.", "Обернена задача: панель на 1 м над дном освітлена прямим світлом, лише якщо глибина кратера менша за {0} діаметра, на 2 м лише якщо менша за {1}. Тоді повідомлене живлення одразу після посадки вказує на зношений мілкий кратер або панель високо на апараті, що лежить на боці; в обох випадках це значно менше, ніж потрібно обігрівачам і радіо."),
        ["inc.predict.lede"] = ("For each lunar day after landing: share of kept draws with any power, first and last powered time as median (90% range), and what was reported in that day.", "Для кожного місячного дня після посадки: частка залишених варіантів з живленням, перший і останній час живлення як медіана (90% розкид) і що повідомлено в цей день."),
        ["inc.predict.day"] = ("Lunar day", "Місячний день"),
        ["inc.predict.sun"] = ("Sun above the horizon, UTC", "Сонце над горизонтом, UTC"),
        ["inc.predict.p"] = ("P(power)", "P(живлення)"),
        ["inc.predict.first"] = ("First power", "Перше живлення"),
        ["inc.predict.last"] = ("Last power", "Останнє живлення"),
        ["inc.predict.reported"] = ("Reported", "Повідомлено"),
        ["inc.predict.none"] = ("No prediction without fit events.", "Без подій навчання прогнозу немає."),
        ["inc.chart.band"] = ("Probability that the panel gives power", "Імовірність, що панель дає живлення"),
        ["inc.chart.pOn"] = ("P(power)", "P(живлення)"),
        ["inc.val.table"] = ("Events against simple models", "Події проти простих моделей"),
        ["inc.val.lede"] = ("Probability each model assigns to the reported event, and the timing error for power loss. Fit rows are in-sample and shown faded. Scores are means over the held-out rows; lower is better.", "Імовірність, яку кожна модель дає повідомленій події, і похибка часу для втрати живлення. Рядки навчання отримано на даних навчання, вони показані блідо. Оцінки це середнє за відкладеними рядками; менше краще."),
        ["inc.val.brier"] = ("Brier score, held out", "Оцінка Brier, відкладені"),
        ["inc.val.log"] = ("Log score, held out", "Логарифмічна оцінка, відкладені"),
        ["inc.model.prior"] = ("Prior", "Апріорна"),
        ["inc.model.prior.def"] = ("All draws before any event is used.", "Усі варіанти до використання подій."),
        ["inc.model.sunUp"] = ("Sun up", "Сонце над горизонтом"),
        ["inc.model.sunUp.def"] = ("Power whenever any part of the Sun is above the terrain horizon, as for an ideal panel that follows the Sun.", "Живлення завжди, коли частина Сонця над горизонтом, як для ідеальної панелі, що стежить за Сонцем."),
        ["inc.model.upright"] = ("Panel up", "Панель угору"),
        ["inc.model.upright.def"] = ("Panel on the top deck facing straight up, posterior median threshold.", "Панель на верхній палубі прямо вгору, медіанний поріг з оцінки."),
        ["inc.model.reported"] = ("Reported", "Повідомлено"),
        ["inc.model.reported.def"] = ("Panel facing the reported direction, horizontal normal, posterior median threshold.", "Панель у повідомленому напрямі, горизонтальна нормаль, медіанний поріг з оцінки."),
        ["inc.model.posterior"] = ("Posterior", "Апостеріорна"),
        ["inc.model.posterior.def"] = ("Kept draws after the fit events.", "Залишені варіанти після подій навчання."),
        ["inc.val.read.slim"] = ("The later contacts all fall in the local afternoon, so any rule that gives power in the afternoon passes them, including Sun up. These events do not separate the models; the posterior is less certain because it retains every attitude the January events allow. Only the no-power event at landing separates them, and Sun up and Panel up fail it. JAXA derived the west-facing attitude from its own post-landing analysis on 25 January, before the afternoon contact; the fit here uses that contact, so the two share information and their agreement is consistency, not independent proof.", "Пізніші зв'язки всі припадають на місцевий день після полудня, тож їх проходить будь-яке правило, що дає живлення вдень, зокрема «Сонце над горизонтом». Ці події не розрізняють моделі; апостеріорна оцінка менш визначена, бо зберігає всі орієнтації, які дозволяють січневі події. Розрізняє моделі лише відсутність живлення під час посадки, і «Сонце над горизонтом» та «Панель угору» її не проходять. Орієнтацію на захід JAXA визначила з власного аналізу після посадки 25 січня, до денного зв'язку; тут навчання використовує цей зв'язок, тож обидві оцінки мають спільну інформацію, і їхній збіг це узгодженість, а не незалежний доказ."),
        ["inc.val.read.im1"] = ("Here the held-out event separates the models: Sun up keeps power until the local sunset two days later, and Panel up loses it days too early. The posterior is the closest, but most of its draws still place the loss too late.", "Тут відкладена подія розрізняє моделі: «Сонце над горизонтом» зберігає живлення до місцевого заходу через дві доби, а «Панель угору» втрачає його на кілька діб раніше. Апостеріорна оцінка найближча, але більшість її варіантів усе одно дає втрату запізно."),
        ["inc.val.none.im2"] = ("No events to score; the crater check is in step 4.", "Немає подій для оцінки; перевірка кратера на кроці 4."),
        ["inc.val.none.blueghost1"] = ("The sunset check is in step 5.", "Перевірка заходу Сонця на кроці 5."),
        ["inc.val.synthetic"] = ("Method check: recovery of known attitudes", "Перевірка методу: відновлення відомих орієнтацій"),
        ["inc.val.syntheticLede"] = ("{0} synthetic landers at the SLIM site with random attitude and threshold, with the same types of events as SLIM (power or no power in the first 2.5 hours, one contact after the true first power), {1} draws each. With the true values generated by the same model, this is simulation-based calibration, a test of the implementation: a 90% interval must contain the true value in about 90% of cases. The second run perturbs the model: a curved panel (three normals 25° apart), 4% of light reflected from the ground and a contact up to 8 days late.", "{0} синтетичних апаратів у місці SLIM з випадковою орієнтацією і порогом, з тими самими типами подій, що й у SLIM (живлення або його відсутність у перші 2.5 години, один сеанс зв'язку після справжнього першого живлення), по {1} вибірок для кожного. Оскільки істинні значення згенеровано тією самою моделлю, це калібрування на симуляціях, перевірка реалізації: 90% інтервал має містити істинне значення приблизно в 90% випадків. Другий запуск збурює модель: вигнута панель (три нормалі через 25°), 4% світла, відбитого від ґрунту, і сеанс зв'язку із запізненням до 8 діб."),
        ["inc.val.covAz"] = ("Azimuth in 90%", "Азимут у 90%"),
        ["inc.val.covEl"] = ("Elevation in 90%", "Висота у 90%"),
        ["inc.val.covTau"] = ("τ in 90%", "τ у 90%"),
        ["inc.val.covFirst"] = ("Day-2 first power in 90%", "Перше живлення дня 2 у 90%"),
        ["inc.val.reliability"] = ("Reliability: P(power on day 2)", "Надійність: P(живлення в день 2)"),
        ["inc.val.relX"] = ("predicted", "прогноз"),
        ["inc.val.relNote"] = ("Perturbed-model run: predicted probability against the observed share, dot size by count; the diagonal is perfect calibration. Brier score {0} against {1} for always predicting the base rate.", "Запуск зі збуреною моделлю: прогнозована імовірність проти частки, що справдилася, розмір точки за кількістю; діагональ відповідає ідеальному калібруванню. Оцінка Brier {0} проти {1} для прогнозу завжди базової частоти."),
        ["inc.val.sensitivity"] = ("Sensitivity of the SLIM result", "Чутливість результату SLIM"),
        ["inc.val.variant"] = ("Change", "Зміна"),
        ["inc.val.az"] = ("Azimuth (90%)", "Азимут (90%)"),
        ["inc.val.kept"] = ("Kept", "Залишено"),
        ["inc.val.share"] = ("P(reported event)", "P(повідомленої події)"),
        ["inc.val.sensNote"] = ("The direction does not depend on the threshold range or on moving the fit windows by 6 hours. A 1° horizon change moves the first sunset by about 2 hours (04:00 to 08:30 UTC on 31 January); that sunset lies inside the 24-hour check window of 31 January, so the check result does not change. The window bounds themselves are not known to the hour.", "Напрям не залежить від діапазону порогу і від зсуву вікон навчання на 6 годин. Зміна горизонту на 1° зсуває перший захід приблизно на 2 години (з 04:00 до 08:30 UTC 31 січня); цей захід лежить усередині 24-годинного вікна перевірки 31 січня, тож результат перевірки не змінюється. Самі межі вікна відомі не з точністю до години."),
        ["inc.sens.base"] = ("As on this page", "Як на сторінці"),
        ["inc.sens.thresholdTo30"] = ("Threshold up to 30%", "Поріг до 30%"),
        ["inc.sens.thresholdTo90"] = ("Threshold up to 90%", "Поріг до 90%"),
        ["inc.sens.windowsEarlier6h"] = ("Fit windows 6 h earlier", "Вікна навчання на 6 год раніше"),
        ["inc.sens.windowsLater6h"] = ("Fit windows 6 h later", "Вікна навчання на 6 год пізніше"),
        ["inc.sens.horizonMinus1"] = ("Horizon 1° lower", "Горизонт на 1° нижче"),
        ["inc.sens.horizonPlus1"] = ("Horizon 1° higher", "Горизонт на 1° вище"),
        ["inc.val.hypotheses"] = ("Readings of the reported 30°", "Прочитання повідомлених 30°"),
        ["inc.val.hypothesis"] = ("Reading", "Прочитання"),
        ["inc.hyp.panel30ToHorizontal"] = ("Array at 30° to the horizontal", "Панель під 30° до горизонту"),
        ["inc.hyp.panel60ToHorizontal"] = ("Array at 60° to the horizontal", "Панель під 60° до горизонту"),
        ["inc.hyp.free"] = ("Any direction", "Будь-який напрям"),
        ["inc.val.hypNote"] = ("Reports state that the lander rests at about 30°. The fit events slightly favour the array at 60° to the horizontal (P(fit events) 0.266 against 0.236, a Bayes factor of 1.13, negligible in practice). For the held-out loss of power all three readings are late, with 20% to 23% of draws inside the reported window. The data do not distinguish the readings.", "За повідомленнями апарат лежить під кутом близько 30°. Події навчання трохи більше підтримують панель під 60° до горизонталі (P(події навчання) 0.266 проти 0.236, коефіцієнт Баєса 1.13, на практиці нехтовно малий). Для відкладеної втрати живлення всі три прочитання дають запізнілий прогноз: у повідомлене вікно потрапляє 20%–23% варіантів. Дані не розрізняють прочитання."),
        ["inc.sim.panelDir"] = ("Panel", "Панель"),
        ["inc.sim.draw"] = ("Posterior draw", "Варіант з апостеріорної вибірки"),
        ["inc.sim.az"] = ("Normal azimuth", "Азимут нормалі"),
        ["inc.sim.el"] = ("Normal elevation (90° = straight up)", "Висота нормалі (90° = прямо вгору)"),
        ["inc.sim.tau"] = ("Power threshold τ, share of full sunlight", "Поріг живлення τ, частка повного світла"),
        ["inc.sim.area"] = ("Panel area", "Площа панелі"),
        ["inc.sim.advanced"] = ("Set by lander body attitude", "Задати через положення корпусу"),
        ["inc.sim.advancedNote"] = ("Tilt of the body from vertical, tilt direction and rotation about the body axis; the result is the direction of the top deck panel.", "Нахил корпусу від вертикалі, напрям нахилу і поворот навколо осі корпусу; результат це напрям панелі на верхній палубі."),
        ["inc.sim.bodyResult"] = ("Top deck panel normal: azimuth {0}, elevation {1}.", "Нормаль панелі верхньої палуби: азимут {0}, висота {1}."),
        ["inc.sim.chartNote"] = ("Days from {0}. Wake power {1} W = τ × panel peak. Coloured bands are the reported events.", "Дні від {0}. Потужність пробудження {1} Вт = τ × пік панелі. Кольорові смуги це повідомлені події."),
        ["inc.events.jst"] = ("Times given as a night or a day in JST are kept as UTC ranges (night = 18:00 to 24:00 JST).", "Час, указаний як ніч чи день за JST, збережено як проміжок в UTC (ніч = 18:00–24:00 JST)."),
        ["inc.sim.pointNote"] = ("This run uses one attitude, the median of each parameter; the result card gives the median over all kept draws, so the two times can differ.", "Цей розрахунок для однієї орієнтації, медіани кожного параметра; картка результату дає медіану по всіх залишених варіантах, тож моменти часу можуть відрізнятися."),
        ["inc.val.evidence"] = ("Evidence from the fit events", "Свідчення подій навчання"),
        ["inc.val.evidenceLede"] = ("P(fit events | hypothesis) is the share of draws from that hypothesis that pass every fit event, the marginal likelihood under the zero-tolerance rule. Its ratio to the uniform hypothesis is the Bayes factor. A hypothesis that passes in every draw reaches the ceiling 1 / P(fit events | uniform), so the factor for the reported west is that ceiling; all factors also depend on the hand-set event windows. When no draw or every draw passes, the value shown is the 95% bound (rule of three), not a standard error.", "P(події навчання | гіпотеза) це частка варіантів цієї гіпотези, що проходять усі події навчання, тобто відособлена правдоподібність за правилом з нульовим допуском. Її відношення до рівномірної гіпотези це коефіцієнт Баєса. Гіпотеза, що проходить у кожному варіанті, сягає стелі 1 / P(події навчання | рівномірна), тож коефіцієнт для повідомленого заходу і є цією стелею; усі коефіцієнти залежать і від вручну заданих вікон подій. Коли не проходить жоден варіант або проходять усі, показано 95% межу (правило трьох), а не стандартну похибку."),
        ["inc.val.pData"] = ("P(fit events)", "P(події навчання)"),
        ["inc.val.factor"] = ("Bayes factor vs uniform", "Коефіцієнт Баєса до рівномірної"),
        ["inc.val.evidenceNote"] = ("The January events exclude an upright lander and favour a west-facing panel by a factor of about 3.6 over an unknown direction; a factor of this size is moderate, not decisive, evidence.", "Події січня виключають апарат у штатному положенні і підтримують панель на захід приблизно в 3.6 раза сильніше за невідомий напрям; коефіцієнт такої величини це помірне, а не вирішальне свідчення."),
        ["inc.ev.uniform"] = ("Any direction (uniform)", "Будь-який напрям (рівномірно)"),
        ["inc.ev.reportedWest"] = ("Facing west, horizontal normal (as reported)", "На захід, горизонтальна нормаль (як повідомлено)"),
        ["inc.ev.westHalf"] = ("Anywhere in the western half", "Будь-де в західній половині"),
        ["inc.ev.upright"] = ("Upright, panel straight up", "Штатне положення, панель прямо вгору"),
        ["inc.val.run"] = ("Run", "Запуск"),
        ["inc.val.run.matched"] = ("Same model, contact within {0} days", "Та сама модель, зв'язок до {0} діб"),
        ["inc.val.run.misspecified"] = ("Perturbed model, contact within {0} days", "Збурена модель, зв'язок до {0} діб"),
        ["inc.val.azErr"] = ("Azimuth error, median", "Похибка азимута, медіана"),
        ["inc.val.brierDay2"] = ("Brier, power on day 2 / base rate", "Brier, живлення в день 2 / базова частота"),
        ["inc.val.syntheticNote"] = ("Coverage stays near 90% in both runs, but the second run perturbs the model only mildly: a late contact still falls at a powered time, which the contact rule allows, and a curved panel with normals 25° apart behaves much like a flat one with another threshold. The test shows that the code is correct, not that the intervals hold for every real failure. The median azimuth error of about 45° shows that two events locate a panel only to within about a quarter of the sky.", "Покриття лишається близько 90% в обох запусках, але другий запуск збурює модель лише трохи: пізній зв'язок усе одно припадає на час із живленням, що правило зв'язку дозволяє, а вигнута панель з нормалями через 25° поводиться майже як пласка з іншим порогом. Тест показує, що код правильний, а не що інтервали витримають будь-яку реальну ваду моделі. Медіанна похибка азимута близько 45° показує, що дві події визначають панель лише з точністю приблизно до чверті неба."),
        ["inc.val.lost"] = ("P(31 Jan loss)", "P(втрата 31 січ.)"),
        ["inc.val.sunset"] = ("Day-1 sunset", "Захід дня 1"),
        ["report.tipRisk"] = ("Tip-over risk", "Ризик перекидання"),
        ["tip.title"] = ("Power after a tip-over", "Живлення після перекидання"),
        ["tip.lede"] = ("If the lander comes to rest on its side, will the panels power it before the battery runs out? For the chosen site and landing window, hundreds of random attitudes are sampled for four panel layouts with the same cell area. The chance of tipping over at all is in the plan robustness card.", "Якщо апарат ляже на бік, чи дадуть панелі живлення до розряду батареї? Для вибраного місця і вікна посадки перебирається кілька сотень випадкових положень для чотирьох компонувань панелей з однаковою площею елементів. Імовірність перекинутися взагалі показує картка «Стійкість плану»."),
        ["tip.back"] = ("Plan robustness", "Стійкість плану"),
        ["tip.cases"] = ("Real tipped landers: SLIM, IM-1, IM-2", "Реальні перекинуті апарати: SLIM, IM-1, IM-2"),
        ["tip.running"] = ("Computing: {0}%", "Розрахунок: {0}%"),
        ["tip.step.inputs"] = ("Site, window and lander", "Місце, вікно і апарат"),
        ["tip.step.result"] = ("Probability of power after a tip-over", "Імовірність живлення після перекидання"),
        ["tip.step.method"] = ("Method", "Метод розрахунку"),
        ["tip.where"] = ("Where and when", "Де і коли"),
        ["tip.site"] = ("Site", "Місце"),
        ["tip.start"] = ("First landing day", "Перший день посадки"),
        ["tip.days"] = ("Landing days to scan", "Днів посадки для перебору"),
        ["tip.prior"] = ("Attitude distribution", "Розподіл положень"),
        ["tip.prior.Uniform"] = ("Any attitude (uniform; 15% tilted under 45°)", "Будь-яке положення (рівномірно; 15% з нахилом до 45°)"),
        ["tip.prior.OnSide"] = ("On its side (60°–100°)", "На боці (60°–100°)"),
        ["tip.lander"] = ("Lander", "Апарат"),
        ["tip.area"] = ("Total cell area", "Загальна площа елементів"),
        ["tip.load"] = ("Safe-mode load", "Навантаження в безпечному режимі"),
        ["tip.batteryHours"] = ("The battery supplies this load for {0} h (80% of the charge usable, 95% efficiency).", "Батарея забезпечує це навантаження {0} год (80% заряду корисні, ККД 95%)."),
        ["tip.defaults"] = ("The lander is the one set for the mission above; the cell area follows from the rated panel power at 30% efficiency. Success means panel power reaching the safe-mode load within the battery time shown above.", "Апарат той самий, що задано для місії вище; площа елементів випливає з номінальної потужності панелей при ККД 30%. Успіх означає, що панелі дають навантаження безпечного режиму раніше, ніж розрядиться батарея."),
        ["tip.layout.top"] = ("Top deck only", "Лише верхня палуба"),
        ["tip.layout.sides4"] = ("Four sides", "Чотири боки"),
        ["tip.layout.topSides"] = ("Top and four sides", "Верх і чотири боки"),
        ["tip.layout.cube"] = ("All six faces", "Усі шість граней"),
        ["tip.layoutNote.top"] = ("Typical for landers designed for an upright attitude.", "Типово для апаратів, розрахованих на штатне положення."),
        ["tip.layoutNote.sides4"] = ("Body-mounted vertical panels.", "Вертикальні панелі на корпусі."),
        ["tip.layoutNote.topSides"] = ("Mixed, area split over five faces.", "Змішане, площа розподілена на п'ять граней."),
        ["tip.layoutNote.cube"] = ("Area split over all faces, bottom included.", "Площа розподілена на всі грані, включно з дном."),
        ["tip.chart"] = ("Probability of power before battery depletion, by landing time", "Імовірність живлення до розряду батареї за часом посадки"),
        ["tip.chartNote"] = ("Days from {0}, one landing every 2 hours, {1} random attitudes each. Shaded: no Sun at the site.", "Дні від {0}, посадка кожні 2 години, по {1} випадкових положень. Затінено: Сонця в місці немає."),
        ["tip.col.layout"] = ("Layout", "Компонування"),
        ["tip.col.mean"] = ("Mean over daylight landings", "Середнє за денними посадками"),
        ["tip.col.best"] = ("Best landing time", "Найкращий час посадки"),
        ["tip.col.worst"] = ("Worst", "Найгірший"),
        ["tip.col.upright"] = ("Upright lander covers the load", "Апарат у штатному положенні покриває навантаження"),
        ["tip.tableNote"] = ("All layouts have the same total cell area, so the difference comes only from the orientation of the cells. Last column: share of daylight landing times at which the same lander in an upright attitude would cover the load.", "Усі компонування мають однакову загальну площу елементів, тож різниця лише в орієнтації елементів. Останній стовпець: частка денних часів посадки, коли той самий апарат у штатному положенні покриває навантаження."),
        ["tip.answer.1"] = ("At {0}, averaged over daylight landing times, {1} of random attitudes give power before the battery runs out with cells on the top deck only, {2} with four side panels and {3} with cells on all six faces.", "У місці {0}, у середньому за денними часами посадки, {1} випадкових положень дають живлення до того, як сяде батарея, з елементами лише на верхній палубі, {2} з чотирма бічними панелями і {3} з елементами на всіх шести гранях."),
        ["tip.answer.2"] = ("For the top-deck lander the landing time is significant: best {0} ({1}), worst {2} ({3}).", "Для апарата з верхньою палубою час посадки суттєвий: найкраще {0} ({1}), найгірше {2} ({3})."),
        ["tip.answer.3"] = ("Even in an upright attitude, the top-deck lander does not cover the load in {0} of daylight landing times: the Sun is too low for a horizontal panel.", "Навіть у штатному положенні апарат з верхньою палубою не покриває навантаження в {0} денних часів посадки: Сонце занадто низько для горизонтальної панелі."),
        ["tip.answer.dark"] = ("There is no Sun at this site in the chosen window.", "У вибраному вікні Сонця в цьому місці немає."),
        ["tip.method.why"] = ("Purpose", "Призначення"),
        ["tip.method.whyText"] = ("A tipped lander depends on its battery until a panel is illuminated. Cell placement and landing time determine whether that takes hours or does not happen at all. The incidents on the next tabs thus become an input to the design and planning of future missions.", "Перекинутий апарат працює від батареї, доки якась панель не буде освітлена. Розташування елементів і час посадки визначають, чи станеться це за години, чи не станеться зовсім. Так випадки на наступних вкладках стають вихідними даними для проєктування і планування майбутніх місій."),
        ["tip.method.limits"] = ("Limits", "Обмеження"),
        ["tip.method.limitsText"] = ("No self-shadowing by the body or legs, no ground-reflected light, no heater load, no small craters below the LOLA resolution; all attitudes are equally likely within the chosen distribution. Absolute shares depend on the lander; the result is the comparison between layouts and landing times.", "Без самозатінення корпусом чи опорами, без світла, відбитого від ґрунту, без обігріву, без малих кратерів, менших за роздільність LOLA; усі положення в межах вибраного розподілу однаково ймовірні. Абсолютні частки залежать від апарата; результатом є порівняння компонувань і часу посадки."),
        ["tip.history"] = ("Actual landings", "Фактичні посадки"),
        ["tip.historyLede"] = ("Probability of power before battery depletion for a random tip-over at the actual landing time and place, with the settings above.", "Імовірність живлення до розряду батареї за випадкового перекидання у фактичні час і місце посадки, з налаштуваннями вище."),
        ["tip.col.case"] = ("Landing", "Посадка"),
        ["tip.col.outcome"] = ("Outcome", "Результат"),
        ["tip.touch.title"] = ("Tip-over at touchdown: model and check", "Перекидання при посадці: модель і перевірка"),
        ["tip.touch.lede"] = ("Whether the lander tips over at all depends on the slope under its legs and on the lateral speed at touchdown. The plan robustness card applies this model to the LOLA slopes within the miss radius.", "Чи перекинеться апарат узагалі, залежить від схилу під опорами і від бічної швидкості в момент торкання. Картка «Стійкість плану» застосовує цю модель до схилів LOLA в радіусі промаху."),
        ["tip.touch.formula"] = ("static       tips without motion if h·tan θ ≥ d, d = r·cos(π/N) / cos δ   (support distance downhill)\nslope        tan θ(L) = tan θ(L0) · (L/L0)^(H-1),  L = 2r,  H = 0.95   (Rosenburg et al. 2011)\ndynamic      footpad caught at touchdown, angular momentum m·y·v about it (Blanco and Mungan 2024):\n             v_tip = sqrt(2g (I/m + ρ²)(ρ - y) / y²),  ρ = sqrt(d² + h²),  y = h·cos θₑ + d·sin θₑ\n             θₑ = atan(tan θ · cos ψ): slope along the direction of motion ψ\nprobability  Monte Carlo over the touchdown point in the miss disc, direction ψ, leg yaw and speed\n             v ~ Rayleigh, 99% below the stated lateral speed; P = share with v ≥ v_tip\npower loss   P(tip) × (1 - share of attitudes with panel power before the battery runs out)", "статика      перекидається без руху, якщо h·tan θ ≥ d, d = r·cos(π/N) / cos δ   (відстань до краю опори вниз по схилу)\nсхил         tan θ(L) = tan θ(L0) · (L/L0)^(H-1),  L = 2r,  H = 0.95   (Rosenburg et al. 2011)\nдинаміка     опора зачіпається при торканні, момент імпульсу m·y·v відносно неї (Blanco, Mungan 2024):\n             v_пер = sqrt(2g (I/m + ρ²)(ρ - y) / y²),  ρ = sqrt(d² + h²),  y = h·cos θₑ + d·sin θₑ\n             θₑ = atan(tan θ · cos ψ): схил у напрямку руху ψ\nімовірність  Монте-Карло за точкою посадки в колі промаху, напрямком ψ, поворотом опор і швидкістю\n             v ~ Релея, 99% нижче за задану бічну швидкість; P = частка v ≥ v_пер\nвтрата живл. P(перекидання) × (1 - частка положень з живленням від панелей до розряду батареї)"),
        ["tip.touch.col.lander"] = ("Landing gear", "Опори"),
        ["tip.touch.col.slope"] = ("Slope", "Схил"),
        ["tip.touch.col.speed"] = ("Lateral speed", "Бічна швидкість"),
        ["tip.touch.col.limit"] = ("Tipping speed, worst direction", "Швидкість перекидання, найгірший напрямок"),
        ["tip.touch.col.model"] = ("Model", "Модель"),
        ["tip.touch.stays"] = ("Stays upright, margin {0}", "Стоїть, запас {0}"),
        ["tip.touch.tips"] = ("Tips over", "Перекидається"),
        ["tip.touch.apollo11"] = ("Apollo 11, 1969", "Apollo 11, 1969 р."),
        ["tip.touch.apollo11.outcome"] = ("Upright (Rogers 1972: lateral speed about 2.7 ft/s, nearly flat surface)", "Стоїть (Rogers 1972: бічна швидкість близько 2.7 фут/с, майже рівна поверхня)"),
        ["tip.touch.lmDesign"] = ("Apollo LM design case", "Проєктний випадок Apollo LM"),
        ["tip.touch.lmDesign.outcome"] = ("Required to stay upright; the toppling boundary lay well within the design envelope (Rogers 1973)", "Мав стояти; межа перекидання лежала значно далі за проєктні умови (Rogers 1973)"),
        ["tip.touch.im1"] = ("IM-1 Odysseus, 2024", "IM-1 Odysseus, 2024 р."),
        ["tip.touch.im1.outcome"] = ("A leg broke while skidding, the lander tipped over (12° slope from LRO; about 1 m/s lateral, as reported)", "Опора зламалася під час ковзання, апарат перекинувся (схил 12° за LRO; бічна швидкість близько 1 м/с за повідомленнями)"),
        ["tip.touch.note"] = ("The rigid model keeps IM-1 upright with only 0.2 m/s to spare: on a 12° slope a Nova-C stance tips at about 1.2 m/s. The reported broken leg is outside the model, which assumes intact legs, no footpad sliding and no soil yield. Apollo LM inertia I/m and Blue Ghost centre of mass are estimates.", "Жорстка модель лишає IM-1 у вертикальному положенні із запасом лише 0.2 м/с: на схилі 12° опори Nova-C перекидаються приблизно при 1.2 м/с. Зламана опора виходить за межі моделі: вона припускає цілі опори, без ковзання і без просідання ґрунту. Момент інерції I/m Apollo LM і центр мас Blue Ghost є оцінками."),
        ["tip.nac.title"] = ("Slope check with LROC NAC terrain models", "Перевірка схилів за моделями рельєфу LROC NAC"),
        ["tip.nac.lede"] = ("The touchdown model takes slopes from LOLA terrain and scales them to the footprint. Stereo terrain models from the LRO Narrow Angle Camera, found through LROC QuickMap and read from the PDS archive, measure the slope at the IM-1 and IM-2 landing points at metre scale.", "Модель посадки бере схили з рельєфу LOLA і перераховує їх на розмір опор. Стереомоделі рельєфу вузькокутної камери LRO, знайдені через LROC QuickMap і прочитані з архіву PDS, вимірюють схил у точках посадки IM-1 та IM-2 в метровому масштабі."),
        ["tip.nac.col.model"] = ("Model input (LOLA)", "Вхід моделі (LOLA)"),
        ["tip.nac.col.fine"] = ("NAC, footprint scale", "NAC, масштаб опор"),
        ["tip.nac.col.wide"] = ("NAC, about 80 m", "NAC, близько 80 м"),
        ["tip.nac.col.product"] = ("Terrain model", "Модель рельєфу"),
        ["tip.nac.im1"] = ("IM-1 Odysseus", "IM-1 (Odysseus)"),
        ["tip.nac.im2"] = ("IM-2 Athena", "IM-2 (Athena)"),
        ["tip.nac.model"] = ("{0} on a {1} m grid, {2} at the footprint", "{0} на сітці {1} м, {2} на розмірі опор"),
        ["tip.nac.fine"] = ("median {0} (10-90%: {1} to {2}), {3} m baseline", "медіана {0} (10-90%: від {1} до {2}), база {3} м"),
        ["tip.nac.wide"] = ("median {0}, {1} m baseline", "медіана {0}, база {1} м"),
        ["tip.nac.scale"] = ("{0} m per pixel", "{0} м на піксель"),
        ["tip.nac.note"] = ("IM-1: the published position (80.13° S, 1.44° E) is rounded to 0.01°, so slopes are taken over the 300 m by 50 m box it allows; the terrain model gives 2588 m elevation there against 2579 m from LROC. The slope is about 12° at every baseline from 6 to 160 m, as reported for the landing, so the 3.6° of the model comes from the 1 km grid: IM-1 lies north of 80° S, outside the 80 m polar terrain. IM-2: slopes within 25 m of the LROC position agree with the model; the 20 m crater the lander tipped into is not resolved at 4 m per pixel.", "IM-1: опублікована позиція (80.13° пд. ш., 1.44° сх. д.) округлена до 0.01°, тому схили взято в усьому прямокутнику 300 на 50 м, який вона допускає; модель рельєфу дає там висоту 2588 м проти 2579 м за LROC. Схил близько 12° на всіх базах від 6 до 160 м, як і повідомлялося для посадки, тож 3.6° у моделі походять від сітки 1 км: IM-1 лежить на північ від 80° пд. ш., поза полярним рельєфом 80 м. IM-2: схили в межах 25 м від позиції LROC узгоджуються з моделлю; кратер діаметром 20 м, у якому перекинувся апарат, при 4 м на піксель не розрізняється."),
        ["tip.outcome.slim"] = ("Nose down, cells west: power restored after several days", "На носі, елементи на захід: живлення відновилося через кілька діб"),
        ["tip.outcome.im1"] = ("On its side, one array lit: six days of power", "На боці, одна панель освітлена: шість діб живлення"),
        ["tip.outcome.im2"] = ("On its side in a crater: ended after 13 h", "На боці в кратері: кінець через 13 год"),
        ["tip.outcome.blueghost1"] = ("Upright: full lunar day", "Штатне положення: увесь місячний день"),
        ["tip.historyNote"] = ("The IM-2 values do not include its 20 m crater, which is not resolved on the LOLA map; the crater check is on its tab.", "Значення для IM-2 не враховують його кратер 20 м, не розрізнений на карті LOLA; перевірка кратера на його вкладці."),
        ["inc.comms.miniNote"] = ("Each chart spans the reported contact window (green) and 18 hours either side; days on the horizontal axis.", "Кожен графік охоплює повідомлене вікно зв'язку (зелене) і по 18 годин з обох боків; на горизонтальній осі дні."),
        ["inc.comms.title"] = ("Ground station visibility", "Видимість наземних станцій"),
        ["inc.comms.lede.jaxa"] = ("A contact needs the Moon above a ground station. Moon elevation at the JAXA stations Misasa 54 m, Usuda 64 m and Uchinoura 34 m from the same ephemeris, station positions from JAXA, Earth rotation as for the DSN check.", "Для зв'язку Місяць має бути над наземною станцією. Висота Місяця над станціями JAXA Місаса 54 м, Усуда 64 м і Утіноура 34 м з тих самих ефемерид, положення станцій від JAXA, обертання Землі як у перевірці DSN."),
        ["inc.comms.lede.dsn"] = ("A contact requires the centre of Earth above the local horizon and the Moon above a ground station. Earth elevation at the site from the same ephemeris and LOLA horizon; the Moon at least 10° above Goldstone, Madrid or Canberra.", "Для зв'язку центр Землі має бути над місцевим горизонтом, а Місяць над наземною станцією. Висота Землі в місці з тих самих ефемерид і горизонту LOLA; Місяць щонайменше на 10° над Голдстоуном, Мадридом чи Канберрою."),
        ["inc.comms.max"] = ("Highest Moon over a JAXA station in the window", "Найвищий Місяць над станцією JAXA у вікні"),
        ["inc.comms.share"] = ("Share of the window at 10° or more", "Частка вікна з висотою від 10°"),
        ["inc.comms.read"] = ("{0} of {1} reported contact windows contain times with the Moon at least 10° above a JAXA station. The Moon is up there {2} of the mission time; for random windows of the same lengths the chance that all {1} contain such a time is about {3}. Contact is only possible while the Moon is up over Japan, and the windows were written as night in Japan, so this is a consistency check of the timeline and the geometry, not evidence about the attitude.", "{0} з {1} повідомлених вікон зв'язку містять моменти, коли Місяць стояв щонайменше на 10° над станцією JAXA. Місяць там над горизонтом {2} часу місії; для випадкових вікон тієї самої довжини ймовірність, що всі {1} містять такий момент, близько {3}. Зв'язок можливий лише тоді, коли Місяць над Японією, а вікна записано як ніч у Японії, тож це перевірка узгодженості хронології і геометрії, а не доказ щодо орієнтації."),
        ["inc.comms.chartJaxa"] = ("Moon over JAXA stations, {0}", "Місяць над станціями JAXA, {0}"),
        ["inc.comms.moonUp"] = ("Moon over JAXA", "Місяць над JAXA"),
        ["inc.comms.min"] = ("10° minimum", "мінімум 10°"),
        ["inc.comms.earthRead"] = ("From landing to the last reported event the centre of Earth was {0} to {1} above the site and above the terrain horizon, and a DSN link was possible {2} of the time. Geometry did not limit the link here.", "Від посадки до останньої повідомленої події центр Землі був на {0}–{1} над місцем і над горизонтом рельєфу, а зв'язок через DSN був можливий {2} часу. Геометрія зв'язок тут не обмежувала."),
        ["inc.comms.chartEarth"] = ("Earth elevation at the site and the terrain horizon in its direction", "Висота Землі в місці і горизонт рельєфу в її напрямку"),
        ["inc.comms.earth"] = ("Earth", "Земля"),
        ["inc.scene.label"] = ("3D view of the lander, its panel, the Sun and Earth", "3D-вигляд апарата, його панелі, Сонця і Землі"),
        ["inc.scene.play"] = ("Play", "Відтворити"),
        ["inc.scene.pause"] = ("Pause", "Пауза"),
        ["inc.scene.time"] = ("Time after landing", "Час після посадки"),
        ["inc.scene.sun"] = ("Sun {0} high, azimuth {1}", "Сонце на висоті {0}, азимут {1}"),
        ["inc.scene.light"] = ("panel gets {0} of full sunlight", "панель отримує {0} повного світла"),
        ["inc.scene.power"] = ("{0} W", "{0} Вт"),
        ["inc.scene.note"] = ("Drag to rotate, scroll to zoom. Blue face: the panel; green arrow: its normal. Yellow disc: the Sun; blue sphere: Earth; violet line: the LOLA terrain horizon. The panel is highlighted when illuminated.", "Перетягування повертає вид, колесо змінює масштаб. Синя грань: панель; зелена стрілка: її нормаль. Жовтий диск: Сонце; синя куля: Земля; фіолетова лінія: горизонт рельєфу LOLA. Панель підсвічується, коли освітлена."),
        ["inc.soft.title"] = ("Robustness: soft likelihood", "Стійкість: м'яка правдоподібність"),
        ["inc.soft.lede"] = ("The strict rule throws away a draw that misses any event by a single step. The soft rule turns each event into a timing error d: how many hours the draw's power state would have to shift for the event to hold (for a no-power window, how far the window must move to fall in the dark). Each event then gets p = ε + (1 − ε)·exp(−½(d/σ)²), so σ is the timing tolerance and ε a floor for events not explained by light, and the same prior draws are weighted by the product instead of kept or dropped. The last columns score the held-out events by mean probability and by mean log loss −ln p (lower is better); Sun up is shown for comparison.", "Строге правило відкидає варіант, що схибив хоч одну подію на один крок. М'яке правило перетворює кожну подію на похибку часу d: на скільки годин мав би зсунутися стан живлення варіанта, щоб подія виконалась (для вікна без живлення: наскільки треба зсунути вікно, щоб воно потрапило в темряву). Кожна подія отримує p = ε + (1 − ε)·exp(−½(d/σ)²), тож σ це допуск за часом, а ε нижня межа для подій, не пояснених світлом, і ті самі апріорні варіанти зважуються на добуток замість «залишити або відкинути». Останні стовпці оцінюють відкладені події середньою ймовірністю і середньою лог-втратою −ln p (менше краще); для порівняння показано «Сонце над горизонтом»."),
        ["inc.soft.rule"] = ("Rule", "Правило"),
        ["inc.soft.ess"] = ("Kept / effective sample", "Залишено / ефективна вибірка"),
        ["inc.soft.check"] = ("Mean P(held-out events)", "Середня P(відкладених подій)"),
        ["inc.soft.log"] = ("Mean log loss", "Середня лог-втрата"),
        ["inc.soft.sunUp"] = ("Sun up, no fit", "Сонце над горизонтом, без навчання"),
        ["inc.soft.strict"] = ("Strict (as above)", "Строге (як вище)"),
        ["inc.soft.row"] = ("Soft, σ = {0} h, ε = {1}", "М'яке, σ = {0} год, ε = {1}"),
        ["inc.soft.read.slim"] = ("The median direction stays at 271° to 272° under every rule; only the interval widens as the timing tolerance increases. The west-facing result does not depend on exact event times. The held-out events are all afternoon power, which the plain Sun-up rule satisfies every time (log loss 0), so they cannot rank the rules; the strict fit only keeps the most probability on them.", "Медіанний напрям лишається 271°–272° за будь-якого правила; зі збільшенням допуску за часом ширшає лише інтервал. Результат «на захід» не залежить від точного часу подій. Відкладені події всі є живленням удень, яке просте правило «Сонце над горизонтом» завжди виконує (лог-втрата 0), тож ранжувати правила вони не можуть; строге навчання лише зберігає на них найбільшу ймовірність."),
        ["inc.soft.read.im1"] = ("The direction stays at 350° under every rule, and the held-out loss of power does not improve (23% strict, 14% at ε = 20%; log loss 1.46 to 1.94): the error lies in the model, not in the strictness of the fit.", "Напрям лишається 350° за будь-якого правила, а прогноз відкладеної втрати живлення не покращується (23% строге, 14% при ε = 20%; лог-втрата від 1.46 до 1.94): похибка в моделі, а не в строгості навчання."),
        ["nav.method"] = ("Method", "Методика"),
        ["method.title"] = ("Method, metrics and errors", "Методика, метрики і похибки"),
        ["method.lede"] = ("Computation method, accuracy and data sources for each quantity.", "Метод розрахунку, точність і джерела даних для кожної величини."),
        ["method.toc"] = ("Contents", "Зміст"),
        ["method.geometry.title"] = ("Sun and Earth positions", "Положення Сонця і Землі"),
        ["method.geometry.text"] = ("Sun and Earth vectors from the Moon's centre come from the DE440 ephemeris through SPICE in the MOON_ME frame, every 30 minutes, with light time and stellar aberration. The site is placed on the 1737.4 km sphere plus its elevation, and directions are taken in its local east-north-up frame. Later years use DE440 with the IAU 2015 lunar rotation model evaluated in TDB.", "Вектори на Сонце і Землю від центру Місяця взято з ефемерид DE440 через SPICE у системі MOON_ME, кожні 30 хв, з часом поширення світла і аберацією. Місце розміщено на сфері 1737.4 км плюс його висота, напрямки визначено в локальній системі схід-північ-зеніт. Наступні роки розраховано з DE440 і моделлю обертання Місяця IAU 2015 у шкалі TDB."),
        ["method.geometry.acc"] = ("7458 positions at all 33 catalogue sites from November 2026 to October 2030 checked against JPL Horizons: largest difference 0.10″ in elevation, median 0.008″. All four years come from SPICE MOON_ME with DE440.", "7458 положення в усіх 33 місцях каталогу з листопада 2026 до жовтня 2030 звірено з JPL Horizons: найбільша різниця 0.10″ за висотою, медіана 0.008″. Усі чотири роки розраховано через SPICE MOON_ME з DE440."),
        ["method.geometry.corr"] = ("Positions include light time and stellar aberration (SPICE LT+S).", "Положення враховують час поширення світла і зоряну аберацію (SPICE LT+S)."),
        ["method.thermal.axis"] = ("z is positive downward; Q_b is the geothermal heat flux at the lower boundary.", "Вісь z спрямована вниз; Q_b це геотермальний потік тепла на нижній межі."),
        ["method.f.sunUp"] = ("Sun up", "Сонце над горизонтом"),
        ["method.f.earthUp"] = ("Earth up", "Земля над горизонтом"),
        ["method.f.radioVisible"] = ("visible", "видимо"),
        ["method.horizon.dem"] = ("The polar DEM is the orbit-adjusted product LDEM_80S_80MPP_ADJ. Santorelli and Wyglinski (2026) found that local maxima picked on the unadjusted PDS product LDEM_80S_20M are orbit-track artefacts 20 to 257 m high at about one site in ten; on the adjusted product none of their selected sites is affected.", "Полярна модель рельєфу — продукт LDEM_80S_80MPP_ADJ, вирівняний за орбітами. Santorelli і Wyglinski (2026) показали, що локальні максимуми, вибрані на невирівняному продукті PDS LDEM_80S_20M, приблизно в одному випадку з десяти є артефактами орбітальних треків висотою від 20 до 257 м; на вирівняному продукті жодна з вибраних ними точок цього не має."),
        ["method.radio.title"] = ("Surface radio link around the landing site", "Наземний радіозв'язок навколо місця посадки"),
        ["method.radio.text"] = ("Line of sight from an antenna on a 4 m mast above the landing point to a receiver 1.5 m above the ground, the geometry of the LTE base station carried by IM-2 and of the LunarRF atlas. 1440 rays every 0.25° of azimuth are traced over the 80 m polar DEM in 80 m steps to 22 km, the free-space range of the 1.8 GHz band in LunarRF, with lunar curvature. A point is visible when the ray to the receiver is not below the highest terrain angle closer to the mast. Shares are weighted by area: within 2 km (the walking radius used for extravehicular activity in LunarRF), within 10 km, and the visible area within 22 km. Available for points south of 80° S.", "Пряма видимість з антени на щоглі 4 м над точкою посадки до приймача на 1.5 м над поверхнею: геометрія базової станції LTE на IM-2 і атласу LunarRF. 1440 променів через 0.25° азимута трасуються по полярній моделі рельєфу 80 м кроком 80 м до 22 км (дальність у вільному просторі для діапазону 1.8 ГГц у LunarRF), з урахуванням кривизни Місяця. Точка видима, якщо промінь до приймача не нижчий за найбільший кут рельєфу ближче до щогли. Частки зважені за площею: у радіусі 2 км (радіус виходу на поверхню в LunarRF), у радіусі 10 км, і видима площа в межах 22 км. Доступно для точок південніше 80° пд. ш."),
        ["method.radio.coverage"] = ("Line of sight is a proxy for coverage. In LunarRF, which adds diffraction and ground reflection (ITU-R P.1812), a landing-site mast at 1.8 GHz covers a median 94% of its line-of-sight area within the free-space range, and 93% at 5.855 GHz within 6.8 km. Close to the mast coverage exceeds line of sight because diffracted paths are still above the threshold: within 2 km the median covered share is 49% against 33% in line of sight.", "Пряма видимість тут є наближенням покриття. У LunarRF, де враховано дифракцію і відбиття від поверхні (ITU-R P.1812), щогла біля місця посадки на 1.8 ГГц покриває в медіані 94% площі прямої видимості в межах дальності у вільному просторі, і 93% на 5.855 ГГц у межах 6.8 км. Біля щогли покриття більше за пряму видимість, бо дифраговані шляхи ще вищі за поріг: у радіусі 2 км медіана покритої частки 49% проти 33% прямої видимості."),
        ["method.radio.check"] = ("Comparison with the LunarRF candidate table (20 m DEM): all 1328 landing-site candidates and every twentieth of the 10 499 ridge candidates, recomputed here on the 80 m DEM.", "Порівняння з таблицею кандидатів LunarRF (рельєф 20 м): усі 1328 кандидатів біля місць посадки і кожен двадцятий із 10 499 кандидатів на хребтах, перераховані тут на рельєфі 80 м."),
        ["method.radio.quantity"] = ("Quantity", "Величина"),
        ["method.radio.class"] = ("Class", "Клас"),
        ["method.radio.landing"] = ("Landing site", "Місце посадки"),
        ["method.radio.ridge"] = ("Ridge", "Хребет"),
        ["method.radio.ours"] = ("Median here", "Медіана тут"),
        ["method.radio.theirs"] = ("Median LunarRF", "Медіана LunarRF"),
        ["method.radio.r"] = ("Correlation", "Кореляція"),
        ["method.radio.mae"] = ("Mean abs. difference", "Середня абс. різниця"),
        ["method.radio.acc"] = ("The 80 m DEM smooths metre-scale relief, so the visible share at landing sites is slightly higher than on the 20 m DEM (+0.03 within 2 km, +6 km² in area). No path loss, antenna pattern, interference or relay is modelled.", "Рельєф 80 м згладжує дрібні нерівності, тому видима частка біля місць посадки трохи більша, ніж на рельєфі 20 м (+0.03 у радіусі 2 км, +6 км² за площею). Втрати на трасі, діаграма антени, завади і ретрансляція не моделюються."),
        ["radio.title"] = ("Surface radio link", "Наземний радіозв'язок"),
        ["radio.none"] = ("No polar terrain at this point.", "Для цієї точки немає полярного рельєфу."),
        ["radio.mapLabel"] = ("Line of sight from a 4 m mast to 22 km, north up; rings at 2 and 10 km", "Пряма видимість зі щогли 4 м до 22 км, північ угорі; кола 2 і 10 км"),
        ["radio.legendSeen"] = ("in line of sight", "у прямій видимості"),
        ["radio.legendHidden"] = ("hidden by terrain", "закрито рельєфом"),
        ["radio.legendMast"] = ("mast", "щогла"),
        ["radio.read"] = ("View from above of 44 × 44 km around the site, north up, relief shaded from the north-west. Blue ground can be reached by a straight radio path from the antenna; grey ground is behind hills or crater rims. Dashed circles: 2 and 10 km.", "Вид згори на 44 × 44 км навколо місця, північ угорі, рельєф підсвічено з північного заходу. До синіх ділянок від антени йде прямий радіопромінь; сірі ділянки закриті пагорбами або валами кратерів. Пунктирні кола: 2 і 10 км."),
        ["radio.north"] = ("N", "Пн"),
        ["radio.eva"] = ("Visible within 2 km", "Видимо в радіусі 2 км"),
        ["radio.near"] = ("Visible within 10 km", "Видимо в радіусі 10 км"),
        ["radio.area"] = ("Visible area to 22 km", "Видима площа до 22 км"),
        ["radio.km2"] = ("{0} km²", "{0} км²"),
        ["radio.note"] = ("Line of sight from an antenna on a 4 m mast to a receiver 1.5 m above the ground, LOLA 80 m. In LunarRF a mast at 1.8 GHz covers about 94% of this area.", "Пряма видимість з антени на щоглі 4 м до приймача на 1.5 м над поверхнею, LOLA 80 м. За LunarRF щогла на 1.8 ГГц покриває близько 94% цієї площі."),
        ["radio.im2"] = ("IM-2 carried the first LTE network on the Moon (Nokia), its base station about 4 m above the ground on an upper panel of the lander. It powered on and returned telemetry, but the lander came to rest on its side, the rover and hopper were not deployed and no surface link was made.", "IM-2 мав першу мережу LTE на Місяці (Nokia), базова станція була приблизно на 4 м над поверхнею на верхній панелі апарата. Вона увімкнулась і передала телеметрію, але апарат ліг на бік, ровер і хопер не було розгорнуто, і наземного з'єднання не встановлено."),
        ["method.horizon.title"] = ("Terrain horizon and visibility", "Горизонт рельєфу і видимість"),
        ["method.horizon.text"] = ("For every 0.5° of azimuth a ray is traced over the LOLA terrain and the maximum elevation angle above an observer 2 m above the surface is kept, including lunar curvature. Catalogue sites south of 80° S use the 80 m polar DEM to 100 km and the global DEM from 100 to 300 km. Points selected on the map south of 80° S use the same 80 m polar DEM to 30 km, loaded in tiles around the point, then the polar DEM averaged to 320 m and the global DEM to 300 km; the result differs from the catalogue method by 0.006° to 0.035° on average. All other points use the global DEM at about 1.9 km to 300 km. The Sun is counted as up when any part of its disc is above that angle, Earth when its centre is.", "Для кожних 0.5° азимута промінь трасується над рельєфом LOLA і зберігається найбільший кут підвищення над спостерігачем на висоті 2 м, з урахуванням кривизни Місяця. Місця каталогу південніше 80° пд. ш. використовують полярну модель 80 м до 100 км і глобальну від 100 до 300 км. Точки, вибрані на карті південніше 80° пд. ш., використовують ту саму полярну модель 80 м до 30 км, завантажену тайлами навколо точки, далі полярну модель, усереднену до 320 м, і глобальну до 300 км; результат відрізняється від методу для каталогу в середньому на 0.006°–0.035°. Решта точок використовує глобальну модель близько 1.9 км до 300 км. Сонце вважається над горизонтом, коли будь-яка частина диска вища за цей кут, Земля коли вищий її центр."),
        ["method.horizon.acc"] = ("Event times are known to within ±15 minutes because of the 30-minute step. Horizon error follows the DEM error (Barker et al. 2021) and resolution.", "Час подій відомий з точністю ±15 хв через крок 30 хв. Похибка горизонту залежить від похибки і роздільності моделі рельєфу (Barker et al. 2021)."),
        ["method.dsn.title"] = ("Deep Space Network link", "Зв'язок через DSN"),
        ["method.dsn.text"] = ("The Moon's direction is transformed from MOON_ME into J2000, precessed to the date (IAU 1976) and rotated by Greenwich mean sidereal time (IAU 1982). Each complex is placed on the WGS84 ellipsoid. A link exists when the centre of Earth is above the site horizon and the Moon is at least 10° above one complex.", "Напрям на Місяць переводиться з MOON_ME у J2000, з прецесією на дату (IAU 1976) і поворотом на середній зоряний час Гринвіча (IAU 1982). Кожен комплекс задано на еліпсоїді WGS84. Зв'язок є, коли центр Землі над горизонтом місця, а Місяць не нижче 10° над одним із комплексів."),
        ["method.dsn.acc"] = ("Minimum elevation {0}° (DSN uplink limit). 12 checks against JPL Horizons agree within 0.002°. Nutation and polar motion are left out; antenna schedules are not modelled.", "Мінімальна висота {0}° (межа DSN для передачі на апарат). 12 перевірок з JPL Horizons збігаються до 0.002°. Нутацію і рух полюса не враховано; розклад антен не моделюється."),
        ["method.height"] = ("Height", "Висота"),
        ["method.power.title"] = ("Solar power and battery", "Сонячна енергія і батарея"),
        ["method.power.text"] = ("Sunlight is scaled by the Sun's distance and by the visible area of its disc above the terrain, and reduced by the share covered by Earth during eclipses. The cell temperature comes from a two-sided radiative balance that includes heat from the ground, and the efficiency decreases as the cells heat up. Four layouts are compared: one-axis tracking, fixed vertical in eight directions, four fixed faces and horizontal.", "Сонячне світло масштабується на відстань до Сонця і видиму площу диска над рельєфом і зменшується на частку, яку закриває Земля під час затемнень. Температура елементів визначається з двостороннього радіаційного балансу з теплом від поверхні, і ККД зменшується з нагріванням. Порівнюються чотири розташування: за Сонцем по одній осі, нерухома вертикальна у восьми напрямках, чотири нерухомі грані і горизонтальна."),
        ["method.param"] = ("Parameter", "Параметр"),
        ["method.value"] = ("Value", "Значення"),
        ["method.basis"] = ("Basis", "Обґрунтування"),
        ["method.unit.ptsPerK"] = ("points per °C", "пункту на °C"),
        ["method.basis.eff"] = ("Triple-junction cells, NASA GRC (Fincannon)", "Триперехідні елементи, NASA GRC (Fincannon)"),
        ["method.basis.beta"] = ("Fits 28% at 50 °C and 22% at 120 °C (Fincannon)", "Узгоджено з 28% при 50 °C і 22% при 120 °C (Fincannon)"),
        ["method.basis.sys"] = ("Fincannon start-of-life factor 0.775 without its temperature and distance terms (modelled explicitly)", "Коефіцієнт Fincannon 0.775 на початку роботи без складових температури і відстані (рахуються окремо)"),
        ["method.basis.optics"] = ("Assumed cover-glass values", "Припущені значення для покривного скла"),
        ["method.basis.dust"] = ("No dust by default; dust on the IM-2 panels was reported", "Без пилу за замовчуванням; для IM-2 повідомлено пил на панелях"),
        ["method.battery"] = ("Battery usable, charge / discharge", "Батарея: корисна ємність, заряд / розряд"),
        ["method.basis.battery"] = ("Assumed Li-ion practice", "Припущення для Li-ion"),
        ["method.load"] = ("Load", "Навантаження"),
        ["method.basis.load"] = ("Assumed, for comparison between sites", "Припущення для порівняння місць"),
        ["method.power.acc"] = ("No degradation over the window, no heater power, no wiring losses beyond the system factor.", "Без деградації за вікно, без обігріву, без втрат у проводці понад системний коефіцієнт."),
        ["method.thermal.title"] = ("Surface temperature", "Температура поверхні"),
        ["method.thermal.text"] = ("Surface temperature comes from one-dimensional heat conduction in the regolith with the parameters Hayne et al. (2017) fitted to LRO Diviner data: properties vary with depth and temperature, and the regolith stores daytime heat and releases it at night.", "Температура поверхні розраховується з одновимірної теплопровідності реголіту з параметрами, які Hayne et al. (2017) підібрали за даними LRO Diviner: властивості змінюються з глибиною і температурою, реголіт накопичує денне тепло і віддає його вночі."),
        ["method.thermal.acc"] = ("At the equator the model gives 385 K at noon, 94 K before dawn and 253 K at depth, in line with Hayne et al. (2017). Near the pole it runs cold, see the Diviner check on the validation page.", "На екваторі модель дає 385 K опівдні, 94 K перед світанком і 253 K на глибині, як у Hayne et al. (2017). Біля полюса вона холодніша, див. перевірку за Diviner на сторінці перевірки."),
        ["method.mission.title"] = ("Mission analysis", "Аналіз місії"),
        ["method.metrics.title"] = ("Metric definitions", "Визначення метрик"),
        ["method.metric.sun"] = ("Sunlit share", "Частка світла"),
        ["method.metric.sun.def"] = ("Share of 30-minute steps in the window with any part of the Sun disc above the terrain horizon.", "Частка 30-хвилинних кроків у вікні, коли будь-яка частина диска Сонця над горизонтом рельєфу."),
        ["method.metric.darkness"] = ("Longest darkness", "Найдовша темрява"),
        ["method.metric.darkness.def"] = ("Longest run of steps without the Sun inside the window, cut at the window edges.", "Найдовший відрізок кроків без Сонця у вікні, обрізаний по межах вікна."),
        ["method.metric.earth"] = ("Earth in view", "Земля у видимості"),
        ["method.metric.earth.def"] = ("Share of steps with the centre of Earth above the terrain horizon.", "Частка кроків, коли центр Землі над горизонтом рельєфу."),
        ["method.metric.gap"] = ("Longest Earth gap", "Найдовша відсутність Землі"),
        ["method.metric.gap.def"] = ("Longest run of steps with the centre of Earth below the terrain horizon.", "Найдовший відрізок кроків, коли центр Землі під горизонтом рельєфу."),
        ["method.metric.link"] = ("DSN link", "Зв'язок DSN"),
        ["method.metric.link.def"] = ("Share of steps with the centre of Earth in view and the Moon at least 10° above Goldstone, Madrid or Canberra.", "Частка кроків, коли центр Землі видно, а Місяць не нижче 10° над Голдстоуном, Мадридом або Канберрою."),
        ["method.metric.eclipse"] = ("Earth in front of the Sun", "Земля перед Сонцем"),
        ["method.metric.eclipse.def"] = ("Steps when the Earth and Sun discs overlap as seen from the site while the Sun is above the terrain horizon.", "Кроки, коли диски Землі й Сонця перекриваються з місця, поки Сонце над горизонтом рельєфу."),
        ["method.ml.title"] = ("Machine learning", "Машинне навчання"),
        ["method.ml.intro"] = ("Two machine learning models were developed: a presence-background classifier that scores the similarity of 1 km polar grid cells to published candidate landing sites in the Artemis regions, and a regression model of the residual between the regolith thermal model and the Diviner Polar Resource Product. Both are ensembles of gradient-boosted decision trees implemented with scikit-learn (Pedregosa et al. 2011). All values below are taken from the trained models.", "Розроблено дві моделі машинного навчання: класифікатор «присутність-фон», що оцінює схожість клітинок полярної сітки 1 км на опубліковані точки-кандидати для посадки в регіонах Artemis, і регресійну модель залишку між тепловою моделлю реголіту і продуктом Diviner Polar Resource Product. Обидві моделі є ансамблями дерев рішень з градієнтним бустингом, реалізованими в бібліотеці scikit-learn (Pedregosa et al. 2011). Усі наведені нижче величини отримано з навчених моделей."),
        ["method.card.purpose"] = ("Objective", "Мета"),
        ["method.card.data"] = ("Data", "Дані"),
        ["method.card.prep"] = ("Preprocessing", "Попередня обробка даних"),
        ["method.card.inputs"] = ("Features", "Ознаки"),
        ["method.card.model"] = ("Algorithm", "Алгоритм"),
        ["method.card.training"] = ("Training", "Навчання"),
        ["method.card.evaluation"] = ("Validation and metrics", "Валідація і метрики"),
        ["method.card.result"] = ("Results", "Результати"),
        ["method.card.limits"] = ("Errors and limitations", "Похибки та обмеження"),
        ["method.card.run"] = ("Reproduce", "Відтворення"),
        ["method.ml.artemis.title"] = ("Similarity to published candidate sites in NASA's Artemis regions", "Схожість на опубліковані точки-кандидати в регіонах Artemis NASA"),
        ["method.ml.artemis.purpose"] = ("NASA has named candidate landing regions near the south pole but has not published individual landing sites. Wueller et al. (2026), an independent study, selected point sites inside these regions using illumination and lander-access criteria derived from LOLA data. The objective is a single score per 1 km cell that combines the computed illumination, Earth visibility and terrain parameters into a measure of similarity to those sites. Since the selection criteria are themselves illumination and slope thresholds, agreement is expected; other NASA selection factors (science value, launch windows, trajectories) are not among the features. The score is shown as the ML layer of the pole map and in the site report.", "NASA визначила регіони-кандидати для посадки біля південного полюса, але не опублікувала окремих місць посадки. Wueller et al. (2026), незалежне дослідження, вибрали точки в цих регіонах за критеріями освітлення і доступності для апарата, отриманими з даних LOLA. Мета: одна оцінка на клітинку 1 км, що поєднує розраховані параметри освітлення, видимості Землі і рельєфу в міру схожості на ці точки. Оскільки критерії відбору самі є порогами освітлення і схилу, збіг очікуваний; інші чинники вибору NASA (наукова цінність, вікна запуску, траєкторії) серед ознак відсутні. Оцінку показано як шар ML на карті полюса і у звіті про місце."),
        ["method.ml.artemis.data"] = ("Positive class: {0} candidate sites in {1} regions from Wueller et al. (2026), Zenodo record 17084058; {3} of them lie in the {4} regions of NASA's October 2024 list, the rest in regions of the 2022 list that were later dropped. Background class: {2} cells of the 1 km polar stereographic grid south of 83° S, excluding cells within 2 km of a site. Feature sources: the LOLA DEM LDEM_80S_80MPP_ADJ (Barker et al. 2023) and one year of DE440 Sun and Earth positions at a 2 h step.", "Позитивний клас: {0} точок-кандидатів у {1} районах з Wueller et al. (2026), запис Zenodo 17084058; {3} з них лежать у {4} районах списку NASA жовтня 2024, решта в районах списку 2022, згодом виключених. Фоновий клас: {2} клітинок полярної стереографічної сітки 1 км південніше 83° пд. ш., без клітинок у межах 2 км від точки. Джерела ознак: модель рельєфу LOLA LDEM_80S_80MPP_ADJ (Barker et al. 2023) і рік положень Сонця і Землі з DE440 з кроком 2 год."),
        ["method.ml.artemis.prep"] = ("Annual Sun and Earth visibility shares were computed for each cell from terrain horizons traced every 1° of azimuth over the DEM averaged to 240 m, with the Sun counted as visible when any part of its disc is above the horizon and Earth when its centre is. Slope is the mean of the 80 m slopes within the cell; elevation is bilinearly resampled from the 800 m grid. Derived features: the maximum Sun share within a 7 × 7 cell window (±3 km); the Euclidean distance to the nearest cell without sunlight, limited to 50 km and log-transformed as ln(1 + d); and relief as the standard deviation of elevation in a 5 × 5 cell window. Site coordinates were projected onto the grid. For the logistic regression, features were standardised and expanded to second-order polynomial terms; the tree models use the features without scaling.", "Річні частки видимості Сонця і Землі розраховано для кожної клітинки з горизонтів рельєфу, побудованих через кожен 1° азимута по моделі рельєфу, усередненій до 240 м; Сонце вважається видимим, коли над горизонтом будь-яка частина диска, Земля коли її центр. Схил є середнім схилів 80 м у межах клітинки; висоту отримано білінійною інтерполяцією із сітки 800 м. Похідні ознаки: максимальна частка Сонця у вікні 7 × 7 клітинок (±3 км); евклідова відстань до найближчої клітинки без сонячного світла, обмежена 50 км і перетворена як ln(1 + d); перепад висот як стандартне відхилення висоти у вікні 5 × 5 клітинок. Координати точок спроєктовано на сітку. Для логістичної регресії ознаки стандартизовано і доповнено поліноміальними членами другого порядку; моделі дерев використовують ознаки без масштабування."),
        ["method.ml.artemis.inputs"] = ("Seven per cell, listed below with permutation importance: the decrease in ROC AUC when one feature is randomly permuted on the held-out sites and local background of each fold (5 repetitions), averaged over the folds. Correlated features share importance.", "Сім на клітинку, перелік нижче з пермутаційною важливістю: зменшення ROC AUC при випадковому перемішуванні однієї ознаки на відкладених точках і локальному фоні кожного розбиття (5 повторень), усереднене за розбиттями. Корельовані ознаки розподіляють важливість між собою."),
        ["method.ml.artemis.model"] = ("Gradient-boosted decision trees (HistGradientBoostingClassifier): maximum depth 3, 200 iterations, learning rate 0.05, balanced class weights. Monotonic constraints: the score is non-decreasing in Sun share, Earth share and maximum Sun share within 3 km, and non-increasing in slope and in distance to permanent shadow; proximity to shadow is favoured deliberately (access to cold traps), while the Sun terms suppress fully dark cells. Elevation and relief are unconstrained. Comparison models: quadratic logistic regression (C = 0.5) and unconstrained gradient-boosted trees with the same settings.", "Градієнтний бустинг дерев рішень (HistGradientBoostingClassifier): максимальна глибина 3, 200 ітерацій, швидкість навчання 0.05, збалансовані ваги класів. Монотонні обмеження: оцінка не спадає з часткою Сонця, часткою Землі і максимальною часткою Сонця в межах 3 км і не зростає зі схилом і відстанню до вічної тіні; близькість до тіні враховано як перевагу свідомо (доступ до холодних пасток), а ознаки Сонця пригнічують повністю темні клітинки. Висота і перепад висот без обмежень. Моделі для порівняння: квадратична логістична регресія (C = 0.5) і градієнтний бустинг дерев без обмежень з тими самими параметрами."),
        ["method.ml.artemis.training"] = ("After validation, the selected model was fitted once on all sites and background cells and applied to every cell south of 83° S. The score is expressed as a percentile among the domain cells (1 to 255). Random seeds are fixed and library versions recorded, so the result is reproducible from the same input data.", "Після валідації вибрану модель навчено один раз на всіх точках і всіх фонових клітинках і застосовано до кожної клітинки південніше 83° пд. ш. Оцінку виражено як процентиль серед клітинок області (від 1 до 255). Початкові значення генераторів випадкових чисел фіксовано, версії бібліотек зафіксовано, тож результат відтворюється з тих самих вхідних даних."),
        ["method.ml.artemis.evaluation"] = ("Leave-one-region-out cross-validation, {0} folds. In each fold the held-out region, all background within 25 km of its centre and the sites of other regions within 25 km are excluded from training (a spatial buffer against leakage between neighbouring regions). The held-out sites are then ranked against the local background within 25 km. Metric: ROC AUC, the probability that a held-out site scores higher than a random local background cell. The local background is the conservative choice; against distant terrain the AUC would be higher. Baselines rank the same test cells by a single feature without training.", "Перехресна валідація з відкладанням одного району, {0} розбиттів. У кожному розбитті відкладений район, увесь фон у межах 25 км від його центру і точки інших районів у межах 25 км виключено з навчання (просторовий буфер проти витоку інформації між сусідніми районами). Далі точки відкладеного району ранжуються проти локального фону в межах 25 км. Метрика: ROC AUC, імовірність того, що відкладена точка отримає вищу оцінку за випадкову клітинку локального фону. Локальний фон дає консервативну оцінку; проти віддаленого рельєфу AUC був би вищим. Базові правила ранжують ті самі тестові клітинки за однією ознакою без навчання."),
        ["method.ml.artemis.result"] = ("Mean AUC {0} over the regions, range {1} to {2}; {7} over the {8} regions NASA kept in 2024. Logistic regression {3}, unconstrained trees {4}. Single feature without training: elevation {9}, Sun share {10}, slope {11}. The constrained model was selected; its mean AUC is {5} below the best unconstrained model. On the final map the sites have a median percentile of {6} (in-sample value, not a validation result).", "Середній AUC {0} по районах, діапазон від {1} до {2}; {7} по {8} районах, залишених NASA у 2024. Логістична регресія {3}, дерева без обмежень {4}. Одна ознака без навчання: висота {9}, частка Сонця {10}, схил {11}. Вибрано модель з обмеженнями; її середній AUC на {5} нижчий, ніж у найкращої моделі без обмежень. На остаточній карті точки мають медіанний процентиль {6} (значення на навчальних даних, а не результат валідації)."),
        ["method.ml.artemis.limits"] = ("The labels represent one published selection, not a NASA selection; the score measures similarity to it, not safety or NASA preference. Elevation alone ranks the sites at AUC {0}, so most of the signal is high, well-illuminated terrain. With few sites per region, the per-region AUC has a wide spread; regions with AUC below 0.8 are highlighted in the table. The 1 km cell does not resolve boulders, small craters or lander-scale slopes. Near 83° S the horizon rays are truncated at the map edge toward the equator, about 100 km short of the 300 km range.", "Мітки відповідають одній опублікованій добірці, а не вибору NASA; оцінка вимірює схожість на неї, а не безпеку чи перевагу NASA. Сама лише висота ранжує точки з AUC {0}, тож більша частина сигналу припадає на високий, добре освітлений рельєф. Через малу кількість точок у районі AUC окремих районів має великий розкид; райони з AUC нижче 0.8 виділено в таблиці. Клітинка 1 км не розрізняє брил, малих кратерів і схилів у масштабі апарата. Біля 83° пд. ш. промені горизонту обрізано краєм карти в бік екватора, приблизно на 100 км коротше за дальність 300 км."),
        ["method.ml.thermal.title"] = ("Correction of the regolith model against Diviner", "Поправка моделі реголіту за Diviner"),
        ["method.ml.thermal.purpose"] = ("Near the pole the regolith heat conduction model is biased cold relative to the Diviner Polar Resource Product. Probable causes, not separated here: scattered and infrared flux from nearby sunlit terrain, included by Paige et al. (2010) but not by the model; sunlit facets smaller than the 1 km horizon grid and the 480 m slope; and differences between the two thermal models, since the Diviner product is itself a model fit. The residual model quantifies how much of this error is predictable from terrain and illumination parameters.", "Біля полюса модель теплопровідності реголіту систематично холодніша за продукт Diviner Polar Resource Product. Імовірні причини тут не розділено: розсіяний та інфрачервоний потік від освітленого рельєфу поруч, який враховують Paige et al. (2010), але не враховує модель; освітлені грані, менші за сітку горизонту 1 км і схил на базі 480 м; відмінності між двома тепловими моделями, оскільки продукт Diviner сам є підгонкою моделі. Модель залишку кількісно визначає, яку частину цієї похибки можна передбачити з параметрів рельєфу та освітлення."),
        ["method.ml.thermal.data"] = ("{0} random cells of the polar grid with a Diviner value. Target: the annual maximum surface temperature and the annual mean temperature 2 cm below the surface from the Diviner Polar Resource Product (Paige et al. 2010) minus the regolith model result for the same cell.", "{0} випадкових клітинок полярної сітки зі значенням Diviner. Цільова змінна: річна максимальна температура поверхні і річна середня температура на глибині 2 см з продукту Diviner Polar Resource Product (Paige et al. 2010) мінус результат моделі реголіту для тієї ж клітинки."),
        ["method.ml.thermal.prep"] = ("For each cell the regolith model was run over a two-year spin-up and one output year, with the cell's terrain horizon and a surface tilted by the slope and aspect over 480 m from the 80 m DEM. Aspect is encoded as its cosine and sine. Diviner values are the mean of the product facets within the 1 km cell.", "Для кожної клітинки модель реголіту розраховано з дворічним періодом розкрутки і одним вихідним роком, з горизонтом рельєфу клітинки і поверхнею, нахиленою за схилом і експозицією на базі 480 м з моделі рельєфу 80 м. Експозицію закодовано косинусом і синусом. Значення Diviner є середнім граней продукту в межах клітинки 1 км."),
        ["method.ml.thermal.inputs"] = ("Model annual maximum and 2 cm annual mean, annual Sun share, slope and aspect over 480 m, mean slope in the 1 km cell, latitude, permanent-shadow indicator.", "Річний максимум і річне середнє на 2 см з моделі, річна частка Сонця, схил і експозиція на базі 480 м, середній схил у клітинці 1 км, широта, індикатор вічної тіні."),
        ["method.ml.thermal.model"] = ("Gradient-boosted regression trees (HistGradientBoostingRegressor): maximum depth 4, 300 iterations, learning rate 0.05. Prediction: regolith model result plus the predicted residual.", "Градієнтний бустинг дерев регресії (HistGradientBoostingRegressor): максимальна глибина 4, 300 ітерацій, швидкість навчання 0.05. Прогноз: результат моделі реголіту плюс передбачений залишок."),
        ["method.ml.thermal.evaluation"] = ("Spatial block cross-validation: cells are grouped into 50 × 50 km blocks and the blocks are split into 5 folds; each fold is predicted by a model trained on the other four. Cells near a block edge may still have training cells within a few kilometres. Metrics against the Diviner product: bias (model minus Diviner), RMSE and Pearson correlation coefficient r. Baseline: regolith model result plus the mean residual of the training folds.", "Просторова блокова перехресна валідація: клітинки згруповано в блоки 50 × 50 км, блоки розбито на 5 частин; кожна частина прогнозується моделлю, навченою на інших чотирьох. Клітинки біля краю блоку можуть мати навчальні клітинки на відстані кількох кілометрів. Метрики відносно продукту Diviner: зсув (модель мінус Diviner), RMSE і коефіцієнт кореляції Пірсона r. Базове правило: результат моделі реголіту плюс середній залишок навчальних частин."),
        ["method.ml.thermal.limits"] = ("The residual model removes about 79% of the mean squared error of the annual maximum, a constant offset alone 46%. Permanently shadowed cells retain a large error: their temperature is controlled by scattered and infrared flux from nearby slopes, which the model does not include. The correction is not applied to other results; site reports show Diviner product values where available.", "Модель залишку усуває близько 79% середньої квадратичної похибки річного максимуму, сталий зсув сам по собі 46%. Клітинки вічної тіні зберігають велику похибку: їхню температуру визначає розсіяний та інфрачервоний потік від сусідніх схилів, якого модель не враховує. Поправку не застосовано до інших результатів; звіти про місця показують значення продукту Diviner там, де вони є."),
        ["method.ml.thermal.metric"] = ("Quantity", "Величина"),
