        ["method.ml.trees"] = ("Constrained trees", "Дерева з обмеженнями"),
        ["method.ml.linear"] = ("Logistic", "Логістична"),
        ["method.incidents.title"] = ("Tipped landers", "Перекинуті апарати"),
        ["method.incidents.text"] = ("A lander resting on its side is modelled as a box with flat panels on its faces, rotated by its tilt, the tilt direction and a rotation about its axis. Each panel receives sunlight from the same DE440 and LOLA horizon chain as the rest of the site. For SLIM and IM-1 the unknown panel direction is estimated by Monte Carlo rejection (zero-tolerance approximate Bayesian computation) from the first reported events and checked on later ones against simple baselines; the method itself is checked on 200 synthetic landers. For IM-2 the rim of its 20 m crater is added from measured depth-to-diameter ratios (Stopar et al. 2017, Pike 1977); Blue Ghost, which landed upright, is the control case.", "Апарат на боці моделюється як коробка з пласкими панелями на гранях, повернута на кут нахилу, у бік нахилу і навколо своєї осі. Кожна панель отримує сонячне світло з того самого ланцюжка DE440 і горизонту LOLA, що й решта сайту. Для SLIM і IM-1 невідомий напрям панелі оцінюється методом Монте-Карло з відкиданням (наближене баєсове обчислення з нульовим допуском) за першими повідомленими подіями і перевіряється на пізніших проти простих базових правил; сам метод перевірено на 200 синтетичних апаратах. Для IM-2 додано вал його кратера 20 м за виміряними співвідношеннями глибини до діаметра (Stopar et al. 2017, Pike 1977); Blue Ghost у штатному положенні є контрольним випадком."),
        ["method.errors.title"] = ("Error budget", "Бюджет похибок"),
        ["method.errors.check"] = ("How it was checked", "Як перевірено"),
        ["method.err.ephemeris"] = ("Sun and Earth direction", "Напрям на Сонце і Землю"),
        ["method.err.ephemeris.size"] = ("Up to about 0.1″", "До приблизно 0.1″"),
        ["method.err.ephemeris.check"] = ("7458 positions against JPL Horizons", "7458 положення проти JPL Horizons"),
