        ["method.err.years.size"] = ("Within 0.003°", "У межах 0.003°"),
        ["method.err.years.check"] = ("First year computed without SPICE and compared with the SPICE MOON_ME solution", "Перший рік розраховано без SPICE і порівняно з розв'язком SPICE MOON_ME"),
