        ["method.err.horizonPolar.check"] = ("Gläser et al. (2014): 92.2% and 92.7% of the year lit against 92.0% and 92.3%", "Gläser et al. (2014): 92.2% і 92.7% року на сонці проти 92.0% і 92.3%"),
        ["method.err.horizonGlobal"] = ("Global horizon", "Глобальний горизонт"),
        ["method.err.horizonGlobal.size"] = ("Mean 0.11° between implementations; relief under 2 km not resolved", "У середньому 0.11° між реалізаціями; рельєф менший за 2 км не розрізняється"),
        ["method.err.horizonGlobal.check"] = ("Two independent implementations, Apollo 15 and Apollo 17", "Дві незалежні реалізації, Apollo 15 і Apollo 17"),
        ["method.err.time"] = ("Event times", "Час подій"),
        ["method.err.time.size"] = ("±15 min", "±15 хв"),
