        ["method.err.power.check"] = ("Cell constants from NASA GRC", "Сталі елементів з NASA GRC"),
        ["method.err.thermal"] = ("Surface temperature", "Температура поверхні"),
        ["method.err.thermal.size"] = ("Equator within a few K; near the pole annual maximum bias −29 K (RMSE 43 K), RMSE 31 K with a constant offset, 20 K after the ML residual", "Екватор у межах кількох K; біля полюса зсув річного максимуму −29 K (RMSE 43 K), RMSE 31 K зі сталим зсувом, 20 K після ML-поправки"),
        ["method.err.thermal.check"] = ("4000 polar cells against the Diviner Polar Resource Product; equatorial noon and pre-dawn against Hayne et al. (2017)", "4000 полярних клітинок проти Diviner Polar Resource Product; екваторіальний полудень і світанок проти Hayne et al. (2017)"),
        ["method.err.ml"] = ("ML similarity", "ML-схожість"),
        ["method.err.ml.size"] = ("Mean AUC 0.91 on held-out regions (elevation alone 0.87)", "Середній AUC 0.91 на відкладених районах (лише висота 0.87)"),
        ["method.err.ml.check"] = ("Leave one region out, 16 folds", "Відкладання району, 16 разів"),
        ["method.ml.f.sun"] = ("Annual Sun share", "Річна частка Сонця"),
