        ["method.ml.f.relief"] = ("Relief within 5 km (standard deviation)", "Перепад висот у межах 5 км (стандартне відхилення)"),
        ["report.ml.title"] = ("Likeness to published Artemis candidate sites (machine learning)", "Схожість на опубліковані кандидатні місця Artemis (машинне навчання)"),
        ["report.ml.of100"] = ("out of 100", "зі 100"),
        ["report.ml.text"] = ("This 1 km cell scores higher than {0}% of all cells south of 83° S on a model trained on 130 published candidate sites in NASA's Artemis regions (Wueller et al. 2026).", "Ця клітинка 1 км має вищу оцінку, ніж {0}% усіх клітинок південніше 83° пд. ш., за моделлю, навченою на 130 опублікованих точках-кандидатах у регіонах Artemis NASA (Wueller et al. 2026)."),
        ["report.ml.outside"] = ("The model covers only south of 83° S, where all 130 candidate sites lie.", "Модель охоплює лише південніше 83° пд. ш., де лежать усі 130 точок-кандидатів."),
        ["report.ml.note"] = ("A likeness to one published site selection on yearly Sun, Earth, slope and terrain at 1 km, not a safety rating or NASA's view. The method page compares it with regions left out of training and with single-input baselines.", "Схожість на одну опубліковану добірку місць за Сонцем, Землею, схилом і рельєфом за рік у сітці 1 км, а не оцінка безпеки чи погляд NASA. На сторінці методики її порівняно з районами, не використаними в навчанні, і з базовими лініями з однієї ознаки."),
        ["report.regolith.title"] = ("Regolith temperature model", "Модель температури реголіту"),
        ["report.regolith.mean"] = ("Mean surface temperature", "Середня температура поверхні"),
        ["report.regolith.deep"] = ("Temperature at about 0.6 m depth", "Температура на глибині близько 0.6 м"),
        ["report.regolith.sunlitMin"] = ("Minimum while sunlit", "Мінімум при Сонці"),
        ["report.regolith.darkMin"] = ("Minimum in darkness", "Мінімум у темряві"),
        ["report.regolith.simple"] = ("Radiative equilibrium without heat storage, maximum", "Радіаційна рівновага без накопичення тепла, максимум"),
        ["report.regolith.tilt"] = ("Surface tilt used", "Нахил поверхні в моделі"),
        ["report.regolith.tiltValue"] = ("{0}°, aspect {1}°", "{0}°, експозиція {1}°"),
        ["report.diviner.title"] = ("LRO Diviner Polar Resource Product at this 1 km cell", "LRO Diviner Polar Resource Product у цій клітинці 1 км"),
        ["report.diviner.max"] = ("Annual maximum, surface", "Річний максимум, поверхня"),
        ["report.diviner.avg"] = ("Annual average, 2 cm deep", "Середнє за рік, 2 см углиб"),
        ["report.diviner.measured"] = ("Diviner product", "Продукт Diviner"),
        ["report.diviner.model"] = ("Shadowline model, full year", "Модель Shadowline, повний рік"),
        ["report.diviner.ice"] = ("Water ice would be stable below {0} m at the shallowest point of this cell (Diviner ice depth).", "Водяний лід був би стабільним глибше {0} м у найсприятливішій точці цієї клітинки (глибина льоду за Diviner)."),
        ["report.diviner.iceSurface"] = ("Water ice would be stable at the surface here: a cold trap.", "Водяний лід тут був би стабільним на поверхні: холодна пастка."),
        ["report.diviner.noIce"] = ("Too warm for stable water ice within 2.9 m of the surface.", "Надто тепло для стабільного водяного льоду в межах 2.9 м від поверхні."),
        ["report.diviner.note"] = ("Diviner values are the mean of the Polar Resource Product facets in the cell; the product is calculated by a thermal model fitted to Diviner observations (Paige et al. 2010). Across 4000 polar cells the Shadowline physics model is colder, mainly because it does not include scattered and infrared flux from nearby terrain.", "Значення Diviner це середнє граней Polar Resource Product у клітинці; продукт пораховано тепловою моделлю, підігнаною до спостережень Diviner (Paige et al. 2010). На 4000 полярних клітинках фізична модель Shadowline холодніша, головно тому, що не враховує розсіяного та інфрачервоного потоку від навколишнього рельєфу."),
        ["validation.lola.title"] = ("Sunlight and Earth visibility against the LOLA polar illumination maps", "Освітлення і видимість Землі проти карт полярного освітлення LOLA"),
        ["validation.lola.lede"] = ("The annual Sun share of the 1 km south polar map is compared with the LOLA average visibility maps (Mazarico et al. 2011), produced by the LOLA team with an independent code from LOLA topography over a multi-year period. The 240 m LOLA pixels are averaged in each 1 km cell; {0} cells from 80° S to the pole. Both products count the Sun as visible when any part of its disc is above the local horizon.", "Річна частка Сонця полярної карти 1 км порівнюється з картами середньої видимості LOLA (Mazarico et al. 2011), які команда LOLA побудувала незалежним кодом з рельєфу LOLA за багаторічний період. Пікселі LOLA 240 м усереднено в кожній клітинці 1 км; {0} клітинок від 80° пд. ш. до полюса. Обидва продукти вважають Сонце видимим, коли над місцевим горизонтом є будь-яка частина диска."),
        ["validation.lola.r"] = ("correlation r, Sun share", "кореляція r, частка Сонця"),
        ["validation.lola.bias"] = ("mean difference, Shadowline minus LOLA", "середня різниця, Shadowline мінус LOLA"),
        ["validation.lola.mae"] = ("mean absolute difference", "середня абсолютна різниця"),
        ["validation.lola.within"] = ("cells within ±0.05", "клітинок у межах ±0.05"),
        ["validation.lola.hist"] = ("Difference of the Sun share per 1 km cell, Shadowline minus LOLA", "Різниця частки Сонця в клітинці 1 км, Shadowline мінус LOLA"),
        ["validation.lola.histNote"] = ("Bins of 0.025, logarithmic count axis. Larger differences concentrate at the map edge, where horizon rays toward the equator are truncated by the map boundary.", "Інтервали 0.025, логарифмічна вісь кількості. Більші різниці зосереджені біля краю карти, де промені горизонту в бік екватора обрізано межею карти."),
        ["validation.lola.psr"] = ("Cells without any sunlight: Shadowline {0}, LOLA {1}, both {2}. Shadowline covers one year; a cell lit only in some years of the 18.6-year nutation cycle counts as shadow there.", "Клітинок без жодного освітлення: Shadowline {0}, LOLA {1}, спільних {2}. Shadowline охоплює один рік; клітинка, освітлена лише в окремі роки 18.6-річного циклу нутації, рахується в ньому як тінь."),
        ["validation.lola.earth"] = ("Earth: the site counts the Earth as visible when its centre is above the horizon, LOLA when any part of its disc is. This difference in definition shifts the Shadowline share by {0} on average over the map.", "Земля: сайт вважає Землю видимою, коли над горизонтом її центр, а LOLA, коли над горизонтом будь-яка частина диска. Через цю різницю визначень частка Shadowline в середньому по карті зміщена на {0}."),
        ["validation.lola.sites"] = ("Catalogue sites south of 65° S", "Місця каталогу південніше 65° пд. ш."),
        ["validation.lola.col.oursSun"] = ("Shadowline Sun, 4 years", "Shadowline, Сонце, 4 роки"),
        ["validation.lola.col.lolaSun"] = ("LOLA Sun (3 x 3 range)", "LOLA, Сонце (діапазон 3 x 3)"),
        ["validation.lola.col.oursEarth"] = ("Shadowline Earth, centre / any part", "Shadowline, Земля, центр / будь-яка частина"),
        ["validation.lola.col.lolaEarth"] = ("LOLA Earth, any part", "LOLA, Земля, будь-яка частина"),
        ["validation.lola.col.res"] = ("LOLA pixel", "Піксель LOLA"),
        ["validation.lola.m"] = ("m", "м"),
        ["validation.lola.sitesNote"] = ("Shadowline values use the site horizon and the ephemeris of 2026-2030. LOLA values are taken at the site pixel; the range covers the 3 x 3 neighbouring pixels (60 m south of 85.2° S, 240 m elsewhere). Planned targets marked ≈ have approximate coordinates. Where the range is wide, the point lies on a steep illumination gradient and a single-point comparison is not meaningful.", "Значення Shadowline використовують горизонт місця і ефемериди 2026-2030. Значення LOLA взято в пікселі місця; діапазон охоплює 3 x 3 сусідні пікселі (60 м південніше 85.2° пд. ш., 240 м деінде). Майбутні цілі з позначкою ≈ мають наближені координати. Де діапазон широкий, точка лежить на крутому перепаді освітлення і порівняння в одній точці не має сенсу."),
        ["validation.lola.why"] = ("Expected sources of difference: one year (map) or four years (sites) against a multi-year LOLA average; observer height 2 m against the surface; a 30 min time step against 1 h; horizons from LDEM_80S_80MPP_ADJ (averaged to 240 m for the map) against the LOLA topography used by Mazarico et al. The positive mean difference is in the direction expected from the higher observer. Source: PDS Geosciences Node, LRO LOLA RDR extras/illumination.", "Очікувані джерела різниці: один рік (карта) або чотири роки (місця) проти багаторічного середнього LOLA; висота спостерігача 2 м проти поверхні; крок 30 хв проти 1 год; горизонти з LDEM_80S_80MPP_ADJ (для карти усереднено до 240 м) проти рельєфу LOLA, використаного Mazarico et al. Додатна середня різниця відповідає напрямку, очікуваному від вищого спостерігача. Джерело: PDS Geosciences Node, LRO LOLA RDR extras/illumination."),
        ["validation.thermal.title"] = ("Surface temperature against LRO Diviner", "Температура поверхні проти LRO Diviner"),
        ["validation.thermal.lede"] = ("4000 random 1 km cells south of 80° S, a full year of the regolith model each, compared with the Diviner Polar Resource Product. That product is itself a thermal model fitted to Diviner observations (Paige et al. 2010), so this compares two models, one of them constrained by Diviner, not a model with direct measurements.", "4000 випадкових клітинок 1 км південніше 80° пд. ш., для кожної рік моделі реголіту, порівняно з Diviner Polar Resource Product. Цей продукт сам є тепловою моделлю, підігнаною до спостережень Diviner (Paige et al. 2010), тож тут порівнюються дві моделі, одна з яких обмежена даними Diviner, а не модель із прямими вимірами."),
        ["validation.thermal.variant"] = ("Model", "Модель"),
        ["validation.thermal.maxBias"] = ("Annual max, bias", "Річний максимум, зсув"),
        ["validation.thermal.maxRmse"] = ("Annual max, RMSE", "Річний максимум, RMSE"),
        ["validation.thermal.avgBias"] = ("Annual mean 2 cm, bias", "Середнє 2 см, зсув"),
        ["validation.thermal.avgRmse"] = ("Annual mean 2 cm, RMSE", "Середнє 2 см, RMSE"),
        ["validation.thermal.v.simple"] = ("Simple balance, flat, no heat storage", "Проста рівновага, рівна поверхня, без накопичення"),
        ["validation.thermal.v.flat"] = ("Regolith model, flat ground", "Модель реголіту, рівна поверхня"),
        ["validation.thermal.v.tilted"] = ("Regolith model, real slope and aspect (used)", "Модель реголіту, справжні схил і орієнтація (використано)"),
        ["validation.thermal.v.offset"] = ("Regolith model + constant offset, unseen 50 km blocks", "Модель реголіту + сталий зсув, невідомі блоки 50 км"),
        ["validation.thermal.v.ml"] = ("Regolith model + ML residual, unseen 50 km blocks", "Модель реголіту + ML-поправка, невідомі блоки 50 км"),
        ["validation.thermal.scatter"] = ("Annual maximum: model against Diviner", "Річний максимум: модель проти Diviner"),
        ["validation.thermal.sunlit"] = ("Sunlit", "Освітлена"),
        ["validation.thermal.dark"] = ("Never sunlit", "Ніколи не освітлена"),
        ["validation.thermal.axes"] = ("Horizontal: Diviner; vertical: regolith model with slope. The line marks perfect agreement.", "Горизонталь: Diviner; вертикаль: модель реголіту зі схилом. Лінія відповідає повному збігу."),
        ["validation.thermal.reference"] = ("Reference: LRO Diviner Polar Resource Product LRO-L-DLRE-5-PRP-V2.0, south (Paige et al. 2010): annual maximum surface temperature and annual mean temperature 2 cm below the surface, both calculated by a thermal model fitted to Diviner observations.", "Еталон: LRO Diviner Polar Resource Product LRO-L-DLRE-5-PRP-V2.0, південь (Paige et al. 2010): річна максимальна температура поверхні і річна середня температура на глибині 2 см, обидві пораховано тепловою моделлю, підігнаною до спостережень Diviner."),
        ["validation.thermal.mlMethod"] = ("ML residual: gradient-boosted trees on top of the physics model; features: physics maximum and mean, annual sunlit share, slope and aspect at 480 m, mean slope in the cell, latitude, never-sunlit flag; 5-fold cross-validation over 50 km blocks.", "ML-поправка: градієнтний бустинг дерев поверх фізичної моделі; ознаки: максимум і середнє фізичної моделі, річна частка на сонці, схил і експозиція на 480 м, середній схил у клітинці, широта, ознака відсутності Сонця; 5-кратна перехресна перевірка за блоками 50 км."),
        ["validation.thermal.classes"] = ("Annual max error by lighting", "Похибка річного максимуму за освітленням"),
        ["validation.thermal.class"] = ("Cells", "Клітинки"),
        ["validation.thermal.c.neverSunlit"] = ("Never sunlit", "Ніколи не освітлені"),
        ["validation.thermal.c.sunlitUnder20"] = ("Sun under 20% of the year", "Сонце менше 20% року"),
        ["validation.thermal.c.sunlit20to50"] = ("Sun 20 to 50%", "Сонце 20–50%"),
        ["validation.thermal.c.sunlitOver50"] = ("Sun over 50%", "Сонце понад 50%"),
        ["validation.thermal.why"] = ("The model is biased cold. The probable causes are not separated: scattered and infrared flux from nearby sunlit terrain, which Paige et al. (2010) include and which dominates in permanently shadowed craters; facets finer than the 1 km grid; and differences between the two thermal models. On held-out blocks a constant offset removes about half of the mean squared error of the annual maximum, the ML residual about four fifths.", "Модель систематично холодніша. Імовірні причини не розділено: розсіяний та інфрачервоний потік від освітленого рельєфу поруч, який враховують Paige et al. (2010) і який переважає у вічно затінених кратерах; грані, дрібніші за сітку 1 км; відмінності між двома тепловими моделями. На відкладених блоках сталий зсув усуває приблизно половину середньої квадратичної похибки річного максимуму, ML-поправка приблизно чотири п'ятих."),
        ["report.series.title"] = ("Conditions over the window", "Умови протягом вікна"),
        ["report.series.lede"] = ("Shaded bands mark intervals with the Sun below the local horizon. Horizontal axis: days from the window start.", "Затінені смуги позначають інтервали, коли Сонце нижче місцевого горизонту. Горизонтальна вісь: доби від початку вікна."),
        ["report.series.elevation"] = ("Elevation above the flat horizon", "Висота над плоским горизонтом"),
