        ["report.series.battery"] = ("Battery state of charge, 1 m² panel turned to the Sun, 100 W load", "Рівень заряду батареї, панель 1 м², повернута до Сонця, навантаження 100 Вт"),
        ["report.series.floor"] = ("minimum usable charge 20%", "мінімальний заряд 20%"),
        ["report.series.note"] = ("All curves use the same 30-minute steps as the tables. The battery is fully charged at the window start.", "Усі криві побудовано на тих самих 30-хвилинних кроках, що й таблиці. На початку вікна батарея повністю заряджена."),
        ["report.series.notePolar"] = ("Near the pole the regolith model is colder than the Diviner product; see the method page.", "Біля полюса модель реголіту холодніша за продукт Diviner, див. сторінку методики."),
