        ["windows.landingEl"] = ("Sun at landing", "Сонце під час посадки"),
        ["windows.more"] = ("Show more ({0} left)", "Показати ще (лишилось {0})"),
        ["windows.none"] = ("No landing time meets the requirements. Lower the minimum shares or shorten the mission.", "Жоден момент посадки не відповідає вимогам. Зменште мінімальні частки або скоротіть місію."),
        ["about.title"] = ("About Shadowline", "Про Shadowline"),
        ["about.lede"] = ("Sun and Earth visibility above the local terrain horizon for any lunar site and date, computed from the JPL DE440 ephemeris and LOLA topography.", "Видимість Сонця і Землі над місцевим горизонтом рельєфу для будь-якого місця на Місяці і дати за ефемеридами JPL DE440 і топографією LOLA."),
        ["about.facts"] = ("Key numbers", "Ключові числа"),
        ["about.fact.steps"] = ("30-minute time steps per year", "30-хвилинних кроків за рік"),
        ["about.fact.dem"] = ("terrain grid at the south pole", "сітка рельєфу на південному полюсі"),
        ["about.fact.range"] = ("horizon range from each site", "дальність горизонту від кожного місця"),
        ["about.fact.error"] = ("largest difference from JPL Horizons in {0} checks", "найбільша різниця з JPL Horizons у {0} перевірках"),
        ["about.q.title"] = ("Scope", "Призначення"),
        ["about.q.text"] = ("For a selected landing site and date, Shadowline shows the positions of the Sun and Earth relative to the terrain horizon, the time to sunset and Earthset, the solar power on a panel and the availability of a direct radio link to Earth. The plan robustness card then checks what happens when the plan does not work out: the launch slips, the lander misses the point or tips over.", "Для вибраного місця посадки і дати Shadowline показує положення Сонця і Землі відносно горизонту рельєфу, час до заходу Сонця і Землі, сонячну потужність на панелі та доступність прямого радіозв'язку із Землею. Картка «Стійкість плану» перевіряє, що станеться, коли план не спрацює: старт переноситься, апарат промахується або перекидається."),
        ["about.horizon.title"] = ("Terrain horizon", "Горизонт рельєфу"),
        ["about.horizon.alt"] = ("Diagram: the ray from the site to the highest terrain angle defines the local horizon; the Sun is above it, so the site is sunlit.", "Схема: промінь від місця до найвищого кута рельєфу задає місцевий горизонт; Сонце вище нього, тож місце освітлене."),
        ["about.horizon.site"] = ("site", "місце"),
        ["about.horizon.peak"] = ("highest angle", "найвищий кут"),
        ["about.horizon.sun"] = ("Sun", "Сонце"),
        ["about.horizon.ray"] = ("local horizon", "місцевий горизонт"),
        ["about.horizon.flat"] = ("flat horizon", "плаский горизонт"),
        ["about.horizon.text"] = ("From each site, rays are traced every 0.5° of azimuth to 300 km over LOLA terrain, including lunar curvature. Near the south pole the first 100 km use the 80 m polar model and the remainder the global model at about 1.9 km; elsewhere the global model is used throughout. The maximum elevation angle along a ray is the horizon in that direction. The Moon has no atmosphere, so there is no refraction or twilight: a direction is visible exactly when it is above this line. Near the pole the Sun stays within a few degrees of the horizon, so a single ridge separates sunlight from weeks of darkness.", "Від кожного місця промені трасуються через кожні 0.5° азимута на 300 км по рельєфу LOLA з урахуванням кривизни Місяця. Біля південного полюса перші 100 км рахуються по полярній моделі 80 м, решта по глобальній моделі близько 1.9 км; в інших місцях по глобальній моделі на всій довжині. Найбільший кут підвищення вздовж променя є горизонтом у цьому напрямку. На Місяці немає атмосфери, тож немає рефракції і сутінків: напрямок видимий саме тоді, коли він вище цієї лінії. Біля полюса Сонце тримається в межах кількох градусів від горизонту, тому один хребет розділяє освітлення і тижні темряви."),
        ["about.data.title"] = ("Data", "Дані"),
        ["about.data.eph"] = ("Sun and Earth: NASA JPL DE440 through NAIF SPICE in the lunar MOON_ME frame, including libration, light time and stellar aberration. 30-minute steps from 1 Nov 2026 for four years: the first year directly from SPICE, the later years from DE440 with the IAU 2015 lunar rotation model, within 0.003° of SPICE.", "Сонце і Земля: NASA JPL DE440 через NAIF SPICE у місячній системі MOON_ME з урахуванням лібрації, часу поширення світла і зоряної аберації. Крок 30 хв від 1 листопада 2026 на чотири роки: перший рік напряму зі SPICE, наступні з DE440 і моделі обертання Місяця IAU 2015, з різницею до 0.003° від SPICE."),
        ["about.data.dem"] = ("Terrain: LOLA south pole DEM at 80 m (80-90° S) and the global LOLA DEM at 16 pixels per degree elsewhere.", "Рельєф: полярна модель LOLA 80 м (80-90° пд. ш.) і глобальна модель LOLA 16 пікселів на градус для решти Місяця."),
        ["about.data.sites"] = ("Sites: Apollo positions from NSSDCA, other landers from LROC images. Artemis regions from NASA's October 2024 list, named for Artemis III; since February 2026 NASA plans the first crewed landing for Artemis IV. Candidate points inside the regions from Wueller et al. (2026).", "Місця: Apollo з NSSDCA, інші апарати зі знімків LROC. Регіони Artemis зі списку NASA жовтня 2024, названі для Artemis III; з лютого 2026 NASA планує першу пілотовану посадку на Artemis IV. Точки-кандидати в регіонах з Wueller et al. (2026)."),
        ["about.data.history"] = ("Landing-day replays: DE440 positions with light time and stellar aberration around each landing time.", "Повтор дня посадки: положення DE440 з часом поширення світла і зоряною аберацією довкола часу кожної посадки."),
        ["about.data.credits"] = ("Full list of sources and licences", "Повний список джерел і ліцензій"),
        ["about.method.title"] = ("Method", "Метод"),
        ["about.method.sun"] = ("Sun up: any part of the solar disc above the horizon at its azimuth. For power, a partly occulted disc contributes its visible fraction.", "Сонце над горизонтом: будь-яка частина сонячного диска вище горизонту в його азимуті. Для енергії частково закритий диск дає свою видиму частку."),
        ["about.method.earth"] = ("Direct link: the centre of Earth above the site's horizon, and the Moon at least 10° above Goldstone, Madrid or Canberra. Station elevations match JPL Horizons within 0.002°.", "Прямий зв'язок: центр Землі над горизонтом місця, а Місяць не нижче 10° над Голдстоуном, Мадридом чи Канберрою. Висоти для станцій збігаються з JPL Horizons у межах 0.002°."),
        ["about.method.power"] = ("Power: 1361 W/m² scaled by the Sun's distance and the visible area of the disc. Cell efficiency 30% at 28 °C, decreasing by 0.086 percentage points per °C above it (28% at 50 °C, 22% at 120 °C); cell temperature from a two-sided radiative balance with the ground; system factor 0.907 (Fincannon's 0.775 without the temperature and distance terms, which are computed separately). Panel mounts: turned to the Sun, fixed vertical, four fixed faces, horizontal.", "Енергія: 1361 Вт/м² з поправкою на відстань до Сонця і видиму площу диска. ККД елементів 30% при 28 °C, зменшується на 0.086 відсоткового пункту на кожен °C вище (28% при 50 °C, 22% при 120 °C); температура елементів з двостороннього радіаційного балансу з поверхнею; системний коефіцієнт 0.907 (0.775 Fincannon без складових температури і відстані, які рахуються окремо). Варіанти панелей: повернута до Сонця, нерухома вертикальна, чотири нерухомі грані, горизонтальна."),
        ["about.method.thermal"] = ("Temperature: one-dimensional heat conduction in the regolith after Hayne et al. (2017), with density and conductivity increasing with depth and temperature-dependent heat capacity, driven by the visible Sun: about 112 °C at noon and −179 °C before dawn at the equator. Scattered and infrared flux from surrounding terrain is not included.", "Температура: одновимірна теплопровідність реголіту за Hayne et al. (2017), густина і теплопровідність зростають з глибиною, теплоємність залежить від температури, нагрів від видимого Сонця: близько 112 °C опівдні і −179 °C перед світанком на екваторі. Розсіяний та інфрачервоний потік від навколишнього рельєфу не враховано."),
        ["about.method.maps"] = ("Pole maps: horizons for 608 × 608 points at 1 km, then the Sun and Earth every 2 h over the year.", "Карти полюса: горизонти для 608 × 608 точок через 1 км, потім Сонце і Земля кожні 2 год протягом року."),
        ["about.method.where"] = ("All calculations for user-selected sites and dates are performed on demand from the precomputed ephemeris and terrain data.", "Усі розрахунки для вибраних місць і дат виконуються на запит з попередньо розрахованих ефемерид і даних рельєфу."),
        ["about.check.title"] = ("Validation", "Перевірка"),
        ["about.check.horizonsLoading"] = ("Comparison with JPL Horizons is loading.", "Порівняння з JPL Horizons завантажується."),
        ["about.check.horizons"] = ("{0} Sun and Earth positions compared with JPL Horizons: largest difference {1} arcseconds.", "{0} положень Сонця і Землі порівняно з JPL Horizons: найбільша різниця {1} кутових секунд."),
        ["about.check.apollo"] = ("Sun elevation at all six Apollo landings, interpolated to the landing minute, agrees with the Apollo Lunar Surface Journal values within 0.05°.", "Висота Сонця під час усіх шести посадок Apollo, інтерпольована на хвилину посадки, збігається зі значеннями Apollo Lunar Surface Journal у межах 0.05°."),
        ["about.check.pole"] = ("Pole map: the floors of Shackleton, Haworth and Faustini receive no sunlight in the modelled year. At the two Shackleton to de Gerlache ridge points of Gläser et al. (2014) the site horizons give 90% and 92% of the year in sunlight and the 1 km map 92%, against 92% over 19 years in that study.", "Карта полюса: дно кратерів Шеклтон, Хаворт і Фаустіні не отримує сонячного світла за модельний рік. У двох точках хребта між Шеклтоном і де Жерлашем з Gläser et al. (2014) горизонти місць дають 90% і 92% року на сонці, а карта з кроком 1 км 92%, проти 92% за 19 років у цій роботі."),
        ["about.check.terrain"] = ("Horizons computed on demand for user-selected points differ from the precomputed ones by under 0.11° on average.", "Горизонти, розраховані на запит для вибраних користувачем точок, відрізняються від попередньо розрахованих у середньому менш ніж на 0.11°."),
        ["about.check.link"] = ("See every comparison point", "Усі точки порівняння"),
        ["about.limits.title"] = ("Limits", "Обмеження"),
        ["about.limits.dem"] = ("Outside 80° S the terrain resolution is about 1.9 km per pixel, so small craters and boulders are not resolved. Lander-scale slopes require 1-5 m maps.", "За межами 80° пд. ш. роздільність рельєфу близько 1.9 км на піксель, тому малі кратери і брили не розрізняються. Для схилів у масштабі посадкового апарата потрібні карти 1-5 м."),
        ["about.limits.time"] = ("Dates cover 1 Nov 2026 to 1 Nov 2030 plus the landing-day windows. The JPL Horizons comparison covers all catalogue sites over the four years at a 13-day step; the landing-day windows use the IAU 2015 rotation model and agree with SPICE within 0.003°.", "Дати охоплюють період з 1 листопада 2026 до 1 листопада 2030 і вікна дат посадки. Порівняння з JPL Horizons охоплює всі місця каталогу за чотири роки з кроком 13 діб; вікна дат посадки використовують модель обертання IAU 2015 і збігаються зі SPICE у межах 0.003°."),
        ["about.limits.link"] = ("The link model includes only the geometry of the three DSN complexes. Antenna schedules, other missions and relay satellites are not modelled.", "Модель зв'язку враховує лише геометрію трьох комплексів DSN. Розклад антен, інші місії та супутники-ретранслятори не моделюються."),
        ["about.limits.power"] = ("Power excludes dust, panel degradation over months, light reflected from nearby terrain and heater loads. Eclipses of the Sun by Earth are included as the covered fraction of the disc. Efficiency, load and battery figures are nominal assumptions for comparison.", "Енергія не враховує пил, деградацію панелей за місяці, світло, відбите від рельєфу поруч, і навантаження обігрівачів. Затемнення Сонця Землею враховано як закриту частку диска. ККД, навантаження і батарея є номінальними припущеннями для порівняння."),
        ["about.use.6"] = ("How it works: method and formulas, validation against JPL Horizons and Diviner, and the tipped landers SLIM, IM-1, IM-2 and Blue Ghost M1 with the prediction against mission reports.", "Як це працює: метод і формули, перевірка з JPL Horizons і Diviner, а також перекинуті апарати SLIM, IM-1, IM-2 і Blue Ghost M1 з прогнозом проти звітів місій."),
        ["about.use.title"] = ("Workflow", "Порядок роботи"),
        ["about.use.1"] = ("Explore: rotate the Moon, select a site, read the countdowns and the verdicts, then open the surface view.", "Огляд: поверніть Місяць, оберіть місце, перегляньте відліки й вердикти, потім відкрийте вид з поверхні."),
        ["about.use.2"] = ("South pole layers: where sunlight and the Earth link persist longest, slopes, ice stability, temperature and similarity to Artemis candidate sites.", "Шари південного полюса: де освітлення і зв'язок тримаються найдовше, схили, стабільність льоду, температура і схожість з кандидатами Artemis."),
        ["about.use.3"] = ("Plan, Where: candidate zones for the mission profile, the three best pinned, each with plan robustness and a full report.", "Планування, Де: зони-кандидати для профілю місії, три найкращі закріплені, для кожної стійкість плану і повний звіт."),
        ["about.use.5"] = ("Plan, Sky: the sky above one site with sensitivity to date and position, side-by-side comparison and the plan robustness card.", "Планування, Небо: небо над одним місцем з чутливістю до дати й позиції, порівнянням і карткою «Стійкість плану»."),
        ["about.use.4"] = ("Plan, When: all landing windows at a site from 2026 to 2030, and after a launch slip the nearest dates and sites that still meet the requirements.", "Планування, Коли: усі вікна посадки в місці з 2026 по 2030 рік, а після зсуву запуску найближчі дати й місця, що ще відповідають вимогам."),
        ["credits.title"] = ("Sources", "Джерела"),
        ["credits.intro"] = ("Every dataset, image, program and published work the results rest on, with its license. All results are computed from open data. The LROC site photographs are copyrighted website images, used for educational purposes with the credit required by the LROC terms.", "Усі набори даних, зображення, програми й публікації, на яких ґрунтуються результати, з ліцензіями. Усі результати пораховано з відкритих даних. Фото місць LROC є захищеними авторським правом зображеннями з сайту, використаними в освітніх цілях з підписом, якого вимагають умови LROC."),
        ["credits.kind.data"] = ("Data and images", "Дані й зображення"),
        ["credits.kind.software"] = ("Software and fonts", "Програми й шрифти"),
        ["credits.kind.research"] = ("Published research", "Наукові публікації"),
        ["credits.researchIntro"] = ("Works whose methods, constants or results the calculations use. The numbers match the citations in the method notes and site reports.", "Праці, методи, сталі або результати яких використано в обчисленнях. Номери збігаються з посиланнями в описі методу і звітах."),
        ["credits.used"] = ("Used for", "Для чого"),
        ["credits.author"] = ("Credit", "Автори"),
        ["credits.license"] = ("License", "Ліцензія"),
        ["credits.missing"] = ("The source list could not be loaded.", "Не вдалося завантажити список джерел."),
        ["credits.ai"] = ("Use of AI tools", "Використання інструментів ШІ"),
        ["credits.ai.intro"] = ("Declaration for the NASA Space Apps Challenge 2026. The team used the AI tools listed below. The team chose the approach and the data, checked the results against the cited sources and is responsible for the content.", "Декларація для NASA Space Apps Challenge 2026. Команда використовувала інструменти ШІ, наведені нижче. Підхід і дані обирала команда, результати перевірено за наведеними джерелами, відповідальність за зміст несе команда."),
        ["credits.ai.claude"] = ("Claude (Anthropic): writing and reviewing code (C# and Blazor, JavaScript for the 3D scene, Python for the data pipeline and the machine learning models), processing and checking data, searching for sources, drafting the site texts in English and Ukrainian, documentation.", "Claude (Anthropic): написання і перевірка коду (C# і Blazor, JavaScript для 3D-сцени, Python для конвеєра даних і моделей машинного навчання), обробка й перевірка даних, пошук джерел, чернетки текстів сайту англійською та українською, документація."),
        ["credits.ai.elicit"] = ("Elicit: search and screening of scientific publications.", "Elicit: пошук і відбір наукових публікацій."),
        ["credits.ai.gemini"] = ("Gemini and NotebookLM (Google): research and summaries of sources.", "Gemini і NotebookLM (Google): дослідження і стислий виклад джерел."),
        ["credits.ai.data"] = ("No value on the site is produced by a language model. Positions, relief, lighting, temperatures and probabilities are computed by scripts from the cited data; the Artemis similarity layer is a trained model described in How it works. Orbital photos and textures come from NASA and partner archives and are not AI-generated.", "Жодне значення на сайті не створене мовною моделлю. Положення, рельєф, освітлення, температури та ймовірності розраховано скриптами з наведених даних; шар схожості з Artemis є навченою моделлю, описаною в розділі «Як це працює». Орбітальні фото і текстури взято з архівів NASA і партнерів, вони не згенеровані ШІ."),
        ["credits.challenge"] = ("Challenge resources", "Ресурси завдання"),
        ["credits.challengeIntro"] = ("The four resources named by the challenge: what Shadowline takes from each, how, where it appears on the site and why it is used this way.", "Чотири ресурси, які називає завдання: що Shadowline бере з кожного, як, де це видно на сайті і чому зроблено саме так."),
        ["credits.disclaimer"] = ("Shadowline is a team project for the NASA Space Apps Challenge 2026.", "Shadowline є командним проєктом для NASA Space Apps Challenge 2026."),
        ["credits.res.what"] = ("Taken", "Що взято"),
        ["credits.res.how"] = ("How", "Як"),
        ["credits.res.where"] = ("Where on the site", "Де на сайті"),
        ["credits.res.use"] = ("Use", "Як використовується"),
        ["credits.res.why"] = ("Why this way", "Чому саме так"),
        ["credits.res.horizons.title"] = ("JPL Horizons System", "Система ефемерид JPL Horizons"),
        ["credits.res.horizons.what"] = ("Apparent azimuth and elevation of the Sun and Earth seen from the lunar surface, without refraction: 33 catalogue sites, every 13 days from 1 November 2026 to 31 October 2030, 7458 positions.", "Видимі азимут і висота Сонця та Землі з поверхні Місяця без рефракції: 33 місця каталогу, кожні 13 діб з 1 листопада 2026 до 31 жовтня 2030, 7458 положень."),
        ["credits.res.horizons.how"] = ("Horizons API, observer at the geodetic coordinates of each site on body 301 at its LOLA elevation. The 66 requests are made offline and the results are stored with the site data; the site makes no requests to Horizons while it runs.", "API Horizons, спостерігач у геодезичних координатах кожного місця на тілі 301 на висоті за LOLA. 66 запитів зроблено офлайн, результати збережено в даних сайту; під час роботи сайт до Horizons не звертається."),
        ["credits.res.horizons.where"] = ("Validation page: accuracy scale, error by date, scatter and per-site table. Accuracy figures in How it works.", "Сторінка перевірки: шкала точності, похибка за датами, діаграма розсіювання і таблиця за місцями. Числа точності в розділі «Як це працює»."),
        ["credits.res.horizons.use"] = ("Reference for the positions the site computes itself from NAIF SPICE (DE440, MOON_ME_DE440_ME421, LT+S): largest difference 0.10″ in elevation and 0.33″ in azimuth near the zenith, median 0.008″. Horizons uses the same DE440 family, so the check covers reference frames, light time, aberration and site geometry, not the planetary ephemeris.", "Еталон для положень, які сайт розраховує сам за NAIF SPICE (DE440, MOON_ME_DE440_ME421, LT+S): найбільша різниця 0.10″ за висотою і 0.33″ за азимутом біля зеніту, медіана 0.008″. Horizons використовує ту саму сім'ю DE440, тому перевірка охоплює системи координат, час поширення світла, аберацію і геометрію місця, а не планетні ефемериди."),
        ["credits.res.horizons.why"] = ("The site needs Sun and Earth positions every 30 minutes for four years at any point, including coordinates entered by the user, without a network request per point. Positions are therefore computed in the browser from SPICE data prepared offline, and Horizons serves as the reference check.", "Сайту потрібні положення Сонця і Землі кожні 30 хвилин на чотири роки в будь-якій точці, зокрема в координатах, введених користувачем, без мережевого запиту на кожну точку. Тому положення розраховуються в браузері з даних SPICE, підготовлених офлайн, а Horizons слугує еталонною перевіркою."),
        ["credits.res.trek.title"] = ("NASA Moon Trek", "Портал NASA Moon Trek"),
        ["credits.res.trek.what"] = ("LRO WAC mosaics: the global mosaic LRO_WAC_Mosaic_Global_303ppd_v02 and the south pole mosaic LRO_WAC_Mosaic_SPole60_100m_v02.", "Мозаїки LRO WAC: глобальна LRO_WAC_Mosaic_Global_303ppd_v02 і південна полярна LRO_WAC_Mosaic_SPole60_100m_v02."),
        ["credits.res.trek.how"] = ("OGC WMTS tiles without an API key. Level 3 of the global mosaic resampled to 2048 × 1024 pixels; level 4 of the polar mosaic (535 m per pixel) resampled to a polar stereographic map of 60-90° S at 909 m per pixel. In the enlarged map, tiles are loaded from the Moon Trek server as the view zooms in: global mosaic up to level 7 (about 170 m per pixel at the equator), polar mosaic up to level 5 (268 m per pixel), only the tiles in view. Georeferencing checked against named craters.", "Тайли OGC WMTS без ключа API. Рівень 3 глобальної мозаїки переведено в 2048 × 1024 пікселі; рівень 4 полярної мозаїки (535 м на піксель) переведено в полярну стереографічну карту 60-90° пд. ш. з кроком 909 м. У збільшеній карті при наближенні підвантажуються лише видимі тайли з сервера Moon Trek: глобальна мозаїка до рівня 7 (близько 170 м на піксель на екваторі), полярна до рівня 5 (268 м на піксель). Прив'язку перевірено за кратерами з відомими координатами."),
        ["credits.res.trek.where"] = ("2D maps in Explore and Planning: whole Moon and south pole tabs and the enlarged map.", "2D-карти в Огляді та Плануванні: вкладки всього Місяця і південного полюса, збільшена карта."),
        ["credits.res.trek.use"] = ("Background image for picking a point and reading the terrain around it. Light and shadow at a site are computed from the ephemeris and LOLA relief, not taken from the image.", "Фонове зображення для вибору точки і читання рельєфу навколо неї. Світло й тінь у місці розраховуються з ефемерид і рельєфу LOLA, а не беруться із зображення."),
        ["credits.res.trek.why"] = ("WMTS is a documented standard with fixed projections, so a script rebuilds the maps from the same tiles. The 3D globe keeps the NASA SVS colour map: WAC mosaics join images taken at different times of the lunar day, and their shadows would contradict the lighting computed for the chosen moment.", "WMTS є документованим стандартом зі сталими проєкціями, тому скрипт відтворює карти з тих самих тайлів. 3D-глобус лишається на кольоровій карті NASA SVS: мозаїки WAC складено зі знімків різного часу місячної доби, і їхні тіні суперечили б освітленню, розрахованому на вибраний момент."),
        ["credits.res.quickmap.title"] = ("LROC QuickMap", "Вебкарта LROC QuickMap"),
        ["credits.res.quickmap.what"] = ("Used as the map for finding data and as a link target. Every site card opens the same point in QuickMap. Its layers led to two products that are then read from the PDS archive: LROC NAC terrain models at the IM-1 and IM-2 landing points and the Diviner rock abundance map. The LOLA products QuickMap displays are also taken from their primary archives (NASA PGDA and PDS).", "Використовується як карта для пошуку даних і як ціль посилання. Картка кожного місця відкриває ту саму точку в QuickMap. Його шари привели до двох продуктів, які потім прочитано з архіву PDS: моделей рельєфу LROC NAC у точках посадки IM-1 та IM-2 і карти кам'янистості Diviner. Продукти LOLA, які показує QuickMap, також взято з первинних архівів (NASA PGDA і PDS)."),
        ["credits.res.quickmap.how"] = ("The link carries the site extent and projection: equidistant cylindrical below 75°, polar stereographic above. The NAC terrain models (3 and 4 m per pixel) and the Diviner map (128 pixels per degree) are read from PDS by byte ranges around each point, without downloading the full files of 325 MB and 3.3 GB. QuickMap's statistics service answers single interactive queries; batch requests were refused by its security check.", "Посилання передає межі місця і проєкцію: рівнопроміжну циліндричну нижче 75°, полярну стереографічну вище. Моделі рельєфу NAC (3 і 4 м на піксель) і карту Diviner (128 пікселів на градус) прочитано з PDS частинами навколо кожної точки, без завантаження повних файлів розміром 325 МБ і 3.3 ГБ. Сервіс статистики QuickMap відповідає на окремі інтерактивні запити; пакетні запити відхилила його перевірка безпеки."),
        ["credits.res.quickmap.where"] = ("Site card in Explore: QuickMap link and rock fraction for the 29 sites between 70° S and 70° N. Slope check on the Power after tip-over page. LOLA illumination check on the Validation page.", "Картка місця в Огляді: посилання на QuickMap і частка каміння для 29 місць між 70° пд. ш. і 70° пн. ш. Перевірка схилів на сторінці «Живлення після перекидання». Перевірка за освітленістю LOLA на сторінці перевірки."),
        ["credits.res.quickmap.use"] = ("NAC slopes check the touchdown model input: at IM-1 the terrain model gives about 12°, as reported for the landing, while the 1 km grid of the model gives 3.6°. Rock fraction marks boulder hazard, which the touchdown model does not include. The LOLA illumination map checks the computed sunlit fraction near the pole: r 0.985, mean difference +0.011 of the year over 369664 cells.", "Схили NAC перевіряють вхід моделі посадки: у точці IM-1 модель рельєфу дає близько 12°, як і повідомлялося для посадки, а сітка моделі 1 км дає 3.6°. Частка каміння позначає небезпеку від каменів, якої модель посадки не враховує. Карта освітленості LOLA перевіряє розраховану частку року із сонячним світлом біля полюса: r 0.985, середня різниця +0.011 року на 369664 клітинках."),
        ["credits.res.quickmap.why"] = ("Primary files carry a version, a DOI and a license, and a script rebuilds every number from them. QuickMap does what it does best here: finding the right product for a point and showing LRO images at full resolution.", "Первинні файли мають версію, DOI і ліцензію, і скрипт відтворює з них кожне число. QuickMap тут робить те, що вміє найкраще: знаходить потрібний продукт для точки і показує знімки LRO в повній роздільності."),
        ["credits.res.csa.title"] = ("Canadian Space Agency, Moon exploration", "Канадське космічне агентство, дослідження Місяця"),
        ["credits.res.csa.what"] = ("Canada's lunar programme: Canadarm3 for Gateway, Canadian astronauts on Artemis missions, the Lunar Exploration Accelerator Program (LEAP) and the planned Canadian lunar utility rover (concept phase, launch in the 2030s, designed to survive the lunar night of about two weeks at temperatures down to -200 °C). The portal publishes no landing sites, dates or data products.", "Місячна програма Канади: Canadarm3 для Gateway, канадські астронавти в місіях Artemis, програма LEAP і запланований канадський універсальний місяцехід (етап концепції, запуск у 2030-х, розрахований пережити місячну ніч близько двох тижнів за температури до -200 °C). Портал не публікує місць посадки, дат чи продуктів даних."),
        ["credits.res.csa.how"] = ("Read from the CSA pages. Canadian hardware already flown to the Moon was traced through LEAP: HAKUTO-R Mission 1 carried Canadensys cameras and a Mission Control Space Services AI flight computer, and NGC Aerospace received its images to test crater-based navigation.", "Прочитано зі сторінок CSA. Канадське обладнання, яке вже летіло до Місяця, знайдено через LEAP: HAKUTO-R Mission 1 ніс камери Canadensys і бортовий комп'ютер зі штучним інтелектом Mission Control Space Services, а NGC Aerospace отримувала його знімки для перевірки навігації за кратерами."),
        ["credits.res.csa.where"] = ("The HAKUTO-R Mission 1 impact site in the catalogue (group Failed landings, impact sites), with the Canadian payloads in its photo note.", "Місце падіння HAKUTO-R Mission 1 у каталозі (група «Невдалі посадки, місця падіння») з канадськими вантажами в підписі до фото."),
        ["credits.res.csa.use"] = ("The rover requirement to survive the lunar night corresponds to figures the site gives for any point: the longest darkness in Planning and in the recommended sites, and the battery charge simulation in the site finder.", "Вимога до місяцехода пережити місячну ніч відповідає показникам, які сайт дає для будь-якої точки: найдовша темрява в Плануванні та рекомендованих місцях і симуляція заряду батареї в пошуку місць."),
        ["credits.res.csa.why"] = ("CSA publishes no coordinates or vehicle parameters for its rovers. The Canadian Lunar Rover, planned to land on the rim of Haworth crater on a Firefly CLPS mission in 2029, was removed from the CSA plan in 2026, so no Canadian target and no Canadian vehicle preset are added.", "CSA не публікує координат чи параметрів своїх місяцеходів. Канадський місяцехід, який мав сісти на валу кратера Haworth з місією Firefly CLPS у 2029 році, у 2026 році вилучено з планів CSA, тому канадської цілі та пресета канадського апарата не додано."),
