        ["layer.legend.earth"] = ("Share of the year with the centre of Earth above the horizon (direct radio link geometrically possible)", "Частка року, коли центр Землі над горизонтом (прямий радіозв'язок геометрично можливий)"),
        ["layer.legend.slope"] = ("Terrain slope, mean over a 300 m cell from 80 m LOLA data", "Нахил рельєфу, середній по клітинці 300 м з даних LOLA 80 м"),
        ["layer.artemis"] = ("Similarity to published Artemis sites (ML)", "Схожість на опубліковані місця Artemis (ML)"),
        ["layer.artemisShort"] = ("ML", "ML-оцінка"),
        ["layer.legend.artemis"] = ("Machine-learning score: similarity of a 1 km cell to the 130 published candidate sites in NASA's Artemis regions (Wueller et al. 2026), as a percentile among cells south of 83° S", "Оцінка машинного навчання: схожість клітинки 1 км на 130 опублікованих точок-кандидатів у регіонах Artemis NASA (Wueller et al. 2026), у процентилях серед клітинок південніше 83° пд. ш."),
        ["layer.artemisNote"] = ("Similarity to one published site selection; not a safety rating.", "Схожість на одну опубліковану добірку місць, а не оцінка безпеки."),
