        ["layer.note"] = ("80-90° S, year from 1 Nov 2026, 1 km grid, observer 2 m above the surface.", "80-90° пд. ш., рік від 1 листопада 2026, сітка 1 км, спостерігач 2 м над поверхнею."),
        ["layer.slopeNote"] = ("Landing site assessment requires maps at 1-5 m; this layer shows the regional picture.", "Для оцінки місця посадки потрібні карти 1-5 м; цей шар показує регіональну картину."),
