        ["validation.dsn.title"] = ("DSN antennas against JPL Horizons", "Антени DSN проти JPL Horizons"),
        ["validation.dsn.lede"] = ("Moon elevation at Goldstone, Madrid and Canberra, computed from the same data as the link lane.", "Висота Місяця над Голдстоуном, Мадридом і Канберрою, розрахована з тих самих даних, що й смуга зв'язку."),
        ["validation.dsn.station"] = ("Station", "Станція"),
