        ["validation.dsn.diff"] = ("Difference", "Різниця"),
        ["validation.dsn.note"] = ("Largest difference {0}°. The Moon's elevation changes by at most about 0.25° per minute, so a link boundary shifts by no more than a few seconds.", "Найбільша різниця {0}°. Висота Місяця змінюється щонайбільше приблизно на 0.25° за хвилину, тож межа зв'язку зсувається не більше ніж на кілька секунд."),
        ["validation.offline.title"] = ("Checks of the precomputed data", "Перевірки попередньо розрахованих даних"),
        ["validation.offline.years.what"] = ("Years 2027 to 2030", "Роки 2027–2030"),
        ["validation.offline.years.result"] = ("Computed with NAIF SPICE in the MOON_ME frame of DE440 with light time and stellar aberration, the same way as the first year, and checked against JPL Horizons above. The landing-day windows use the IAU 2015 rotation model in TDB and agree with SPICE within 0.003°.", "Розраховано через NAIF SPICE у системі MOON_ME з DE440 з часом поширення світла і зоряною аберацією, так само як перший рік, і звірено з JPL Horizons вище. Вікна дат посадки використовують модель обертання IAU 2015 у шкалі TDB і збігаються зі SPICE у межах 0.003°."),
        ["validation.offline.pole.what"] = ("South pole light map", "Карта освітлення південного полюса"),
        ["validation.offline.pole.result"] = ("The floors of Shackleton, Haworth and Faustini receive no sunlight in the modelled year. At the Shackleton to de Gerlache ridge points of Gläser et al. (2014) the map gives 92% of the year in sunlight, consistent with their 19-year result.", "Дно кратерів Шеклтон, Хаворт і Фаустіні не отримує сонячного світла за модельний рік. У точках хребта між Шеклтоном і де Жерлашем з Gläser et al. (2014) карта дає 92% року на сонці, що узгоджується з їхнім результатом за 19 років."),
        ["validation.offline.global.what"] = ("Horizon for any point", "Горизонт для будь-якої точки"),
        ["validation.offline.global.result"] = ("For Apollo 15 and Apollo 17, two independent implementations of the horizon calculation over the global DEM differ by under 0.11° on average.", "Для Apollo 15 і Apollo 17 дві незалежні реалізації розрахунку горизонту по глобальній моделі рельєфу відрізняються в середньому менш ніж на 0.11°."),
        ["validation.offline.history.what"] = ("Landing day replay", "Відтворення дня посадки"),
        ["validation.offline.history.result"] = ("Sun elevation at the Apollo 11, 12, 14, 15, 16 and 17 landings, interpolated to the landing minute: 10.70°, 5.15°, 10.35°, 12.03°, 14.76° and 13.35°, against 10.65°, 5.19°, 10.36°, 12.05°, 14.76° and 13.33° in the Apollo Lunar Surface Journal, all within 0.05°.", "Висота Сонця під час посадок Apollo 11, 12, 14, 15, 16 і 17, інтерпольована на хвилину посадки: 10.70°, 5.15°, 10.35°, 12.03°, 14.76° і 13.35° проти 10.65°, 5.19°, 10.36°, 12.05°, 14.76° і 13.33° в Apollo Lunar Surface Journal, усі в межах 0.05°."),
        ["validation.details"] = ("All checks", "Усі перевірки"),
        ["validation.details.worst"] = ("The {0} largest differences of {1} checks", "{0} найбільших різниць із {1} перевірок"),
        ["planner.lede"] = ("Select a site and a time. The 3D view, sky chart and timeline show the same moment.", "Оберіть місце і час. 3D-вигляд, карта неба і часова шкала показують один і той самий момент."),
        ["nav.planner"] = ("Planner", "Планувальник"),
        ["nav.replan"] = ("Replan", "Перепланування"),
        ["nav.validation"] = ("Validation", "Перевірка"),
        ["nav.mode"] = ("Interface mode", "Режим інтерфейсу"),
        ["nav.language"] = ("Language", "Мова"),
        ["notFound.title"] = ("Page not found", "Сторінку не знайдено"),
        ["notFound.back"] = ("Return to the start page", "Повернутися на початкову сторінку"),
        ["inc.formula.model"] = ("ŝ(t)          Sun direction at the site from DE440 with light time and aberration, every 30 min\nf(t)          visible fraction of the Sun disc above the LOLA terrain horizon h(az)\nE(t)        = S₀ · (1 au / r(t))² · f(t),   S₀ = 1361 W/m²\nu(t; θ)     = E(t) / S₀ · max(0, n̂ · ŝ(t))          θ = (az, el, τ),  n̂ = n̂(az, el)\non(t; θ)    = [ u(t; θ) ≥ τ ]\nprior       az ~ U(0°, 360°),  sin el ~ U(−1, 1),  τ ~ U(0.02, 0.60)\nlikelihood  L(θ) = Π_k 1[ event k consistent with on(·; θ) ]     (zero-tolerance ABC)\nsoft        L(θ) = Π_k [ ε + (1 − ε) · exp(−½ (d_k(θ) / σ)²) ]   d_k = shift in hours of the power state of θ needed for event k, ε = floor for events not explained by sunlight\n            weights w_i = L(θ_i) on the prior draws (importance sampling), ESS = (Σw)² / Σw²\nposterior   p(θ | events) ∝ prior(θ) · L(θ)  →  kept draws\nprediction  P(on at t) = fraction of kept draws with on(t; θ) = 1\nscores      Brier = (1 − p)²,  log score = −ln max(p, 0.01),  p = predicted probability of the reported event", "ŝ(t)          напрямок на Сонце в місці з DE440 з часом поширення світла й аберацією, кожні 30 хв\nf(t)          видима частка диска Сонця над горизонтом рельєфу LOLA h(az)\nE(t)        = S₀ · (1 au / r(t))² · f(t),   S₀ = 1361 Вт/м²\nu(t; θ)     = E(t) / S₀ · max(0, n̂ · ŝ(t))          θ = (az, el, τ),  n̂ = n̂(az, el)\non(t; θ)    = [ u(t; θ) ≥ τ ]\nапріорі     az ~ U(0°, 360°),  sin el ~ U(−1, 1),  τ ~ U(0.02, 0.60)\nправдоподібність  L(θ) = Π_k 1[ подія k узгоджена з on(·; θ) ]     (ABC з нульовим допуском)\nм'яка       L(θ) = Π_k [ ε + (1 − ε) · exp(−½ (d_k(θ) / σ)²) ]   d_k = потрібний зсув стану живлення θ у годинах для події k, ε = нижня межа для подій, не пояснених освітленням\n            ваги w_i = L(θ_i) на апріорних вибірках (вибірка за значущістю), ESS = (Σw)² / Σw²\nапостеріорі p(θ | події) ∝ prior(θ) · L(θ)  →  збережені вибірки\nпрогноз     P(on у t) = частка збережених вибірок з on(t; θ) = 1\nоцінки      Brier = (1 − p)²,  логарифмічна оцінка = −ln max(p, 0.01),  p = прогнозована ймовірність повідомленої події"),
        ["inc.formula.rim"] = ("rim(h) = atan( (d/D · D − h) / (D/2) )        D = 20 m, h = panel height above the crater floor\nsunlight possible if rim(h) < Sun elevation  ⇔  d/D < (h + D/2 · tan e☉) / D", "rim(h) = atan( (d/D · D − h) / (D/2) )        D = 20 м, h = висота панелі над дном кратера\nосвітлення можливе, якщо rim(h) < висоти Сонця  ⇔  d/D < (h + D/2 · tan e☉) / D"),
        ["tip.formula"] = ("attitude     body up axis uniform on the sphere (or tilt 60°–100° for \"on its side\"), random fall direction and rotation\npanels       flat faces of a box, same total area A for every layout, normal n̂ₖ rotated by the attitude\npower        P(t) = E(t) · η · 0.80 · Σₖ Aₖ · max(0, n̂ₖ · ŝ(t))        E(t) from DE440 and the LOLA horizon\nbattery      T_batt = W · (s₀ − 0.2) · 0.95 / L                         hours of safe-mode load L on battery\nsurvives     first t ≥ t_landing with P(t) ≥ L occurs within T_batt\nrisk         P(survive | landing time) = fraction of N random attitudes that survive", "орієнтація   вісь «вгору» апарата рівномірно на сфері (або нахил 60°–100° для «на боці»), випадковий напрям падіння і поворот\nпанелі       пласкі грані коробки, однакова сумарна площа A для всіх компонувань, нормаль n̂ₖ повернута за орієнтацією\nенергія      P(t) = E(t) · η · 0.80 · Σₖ Aₖ · max(0, n̂ₖ · ŝ(t))        E(t) з DE440 і горизонту LOLA\nбатарея      T_batt = W · (s₀ − 0.2) · 0.95 / L                         годин роботи на батареї з навантаженням безпечного режиму L\nвиживання    перший t ≥ t_посадки з P(t) ≥ L настає в межах T_batt\nризик        P(виживання | час посадки) = частка з N випадкових орієнтацій, що виживають"),
