    public static IEnumerable<string> Keys => Table.Keys;

    public static string Get(string language, string key)
    {
        if (!Table.TryGetValue(key, out var pair))
        {
            return key;
        }

        return language == Ukrainian && pair.Uk.Length > 0 ? pair.Uk : pair.En;
    }

    public static bool IsSupported(string? language) => language is English or Ukrainian;
}
